// SINH TỰ ĐỘNG từ content/nghe-tu/*.json. Không sửa tệp này.
const NTU_DATA={"TU17":{"ten":"Cổ sư","sk":[{"ma":"S01","ten":"Vò cổ đầu","text":["Ngươi đặt vò đất lên tấm ván ở bến {LOC09}. Từ trong vò vọng ra tiếng cào mảnh như móng tay miết qua giấy.","Người bán chỉ cho ngươi chỗ nhét linh thạch qua nắp. Dưới gấu áo ngươi là túi dành tiền trọ, cũng là chỗ cất phần nuôi cổ."],"c":[{"l":"Để riêng phần nuôi cổ","t":"Ngươi rút linh thạch khỏi túi trước khi cất vò. Tối đến, chỗ ngủ chỉ còn mái hiên, nhưng tiếng cào đã lắng.","e":{"st":-1,"res":1,"xp":2}},{"l":"Gửi vò lại người bán","t":"Ngươi xin khất việc nhận vò đến khi có tiền nuôi. Người bán kéo vò về bên chân, còn ngươi giữ được chỗ ngủ qua đêm.","e":{"hp":"5%"}}]},{"ma":"S02","ten":"Cổ cắn chủ","text":["Linh thạch đã cạn từ trước khi ngươi dừng ở quán. Vừa hé nắp vò, ngươi thấy cổ bám lên mép rồi cắn vào kẽ ngón tay.","Vết cắn nóng dần, đến lúc buộc lại nắp ngươi đã khó gập tay. Người coi bếp đặt nước sạch xuống và chỉ lối tới thầy thuốc."],"c":[{"l":"Gửi vò, đi chữa độc","t":"Ngươi nhờ người coi bếp giữ vò đóng kín rồi đi tìm thuốc. Vết nóng dịu xuống, còn chìa hòm đựng vò nằm lại ở quán.","e":{"hp":"5%","res":-1,"st":-1}},{"l":"Mang vò đi tìm linh thạch","t":"Ngươi quấn tay rồi ghé chợ bán món đồ dành đi đường. Có thức nuôi cho cổ, nhưng khi trở về ngươi vẫn phải nhờ người mở nút vải trên tay.","e":{"wound":"doc","res":1}}]},{"ma":"S03","ten":"Giải cổ cho người","text":["Người nhà bệnh nhân dẫn ngươi tới bên giường. Họ giơ chiếc bát lên, cho ngươi thấy những vệt bò chỉ xuất hiện khi nước nguội.","Bệnh nhân muốn tự chọn ai có mặt lúc giải. Ngoài cửa đứng sẵn người đã trả tiền, đòi chứng kiến để biết cổ mang dấu nhà nào."],"c":[{"l":"Giải trước người bệnh chọn","t":"Ngươi đợi người trả tiền ra ngoài rồi bắt đầu giải. Khi cổ rơi vào chén, bệnh nhân tự đẩy chén tới người mình đã gọi vào.","e":{"hd":[3,0],"danh":3,"xp":3}},{"l":"Giữ cổ làm chứng","t":"Ngươi xin người bệnh cho giữ con cổ sau khi tháo phép. Tới sáng, người nhà đem chén niêm đi đối dấu, còn tên bệnh nhân được che dưới mép giấy.","e":{"res":1,"st":1,"hd":[1,0]}}]},{"ma":"S04","ten":"Hạ tình cổ","text":["Một người đặt thư cưới và túi linh thạch cạnh vò của ngươi. Họ muốn người đã trả thư đổi ý trước ngày thuyền rời bến.","Mé dưới thư còn nguyên dấu gấp, như thể người nhận chưa từng mở. Khách chỉ vào phong thư, hỏi ngươi có chịu dùng cổ thay lời mình không."],"c":[{"l":"Trả thù lao và lá thư","t":"Ngươi đẩy vò khỏi tầm tay khách rồi trả lại cả thư lẫn tiền. Lúc ra bến, khách xé phong thư nhưng vẫn cất tờ bên trong.","e":{"hd":[3,0],"tamma":-2}},{"l":"Nhận lời hạ cổ","t":"Ngươi nhận tiền và hạ cổ theo lời khách. Khi gặp lại, người bị hạ tự đưa thư tới nhưng phải bấu vào cột bến mới bước thêm được.","e":{"st":3,"hd":[0,3],"tamma":3}}]},{"ma":"S05","ten":"Trại cổ bị đốt","text":["Khói hun thấp dưới mái trại, và dây treo vò đã bén lửa. Người giữ trại ho bên cổng, chỉ về phía dãy vò còn khóa.","Có tiếng gõ từ kho sau, nơi người nuôi cổ ngủ lại. Cửa trại đang hẹp dần vì cột xà cháy nghiêng vào lối."],"c":[{"l":"Đưa người trong kho ra","t":"Ngươi dẫn họ qua cửa trước khi xà rơi. Lúc đứng được ngoài sân, người giữ trại mới hỏi còn vò nào chưa vỡ.","e":{"deed":"cuu_nguoi","hp":"-5%"}},{"l":"Dời những vò còn kín","t":"Ngươi kéo dãy vò ra sát bờ nước để lửa khỏi bén. Khi quay lại, người trong kho đã thoát qua vách sau, bàn tay bỏng vì tự gỡ phên.","e":{"res":2,"hd":[0,1],"danh":-2}}]},{"ma":"S06","ten":"Cổ vương xuất vò","text":["Những tiếng cào rời rạc trong vò bỗng im. Con cổ còn lại bò lên miệng vò, chân dừng ngay trên đường đất đã rạn.","Người giữ trại mang đến chén linh thạch và chiếc nắp dự phòng. Họ hỏi ngươi có dám mở vò trước mặt những người cùng nuôi hay chưa."],"c":[{"l":"Thử hiệu lệnh trong sân kín","t":"Ngươi dọn sân rồi mở hé vò cho mọi người đứng xem từ ngoài cửa. Cổ chịu dừng theo tiếng gõ, nhưng từ hôm ấy phần nuôi được khóa riêng.","e":{"res":2,"xp":4,"st":-1}},{"l":"Đậy vò, ngừng buổi thử","t":"Ngươi đặt nắp dự phòng lên trước khi con cổ vượt miệng vò. Người xem ra về, còn ngươi phải tìm chỗ giữ vò mới vì đường rạn đã chạy tới đáy.","e":{"tv":3,"tamma":-2}}]},{"ma":"S07","ten":"Dịch cổ lan làng","text":["Dân làng mang chiếu ra hong, tưởng mùi ẩm từ giường làm người nhà sốt. Dưới đường viền chiếu, ngươi thấy vệt cổ bò sang tấm kế bên.","Người gánh hàng xin mở lối ra vì còn mẹ ốm ở bờ bên kia. Người coi kho đứng chờ ngươi nói nên giữ hàng lại hay mở đường cho họ đi."],"c":[{"l":"Tách đồ nhiễm và giải cổ","t":"Ngươi chỉ từng tấm chiếu có vệt, nhờ chủ nhà tự đem ra chỗ riêng. Hàng hóa ở lại qua phiên, còn người cần đi được ngươi xem trước khi qua bến.","e":{"hd":[3,0],"danh":5,"mp":"-10%"}},{"l":"Theo gánh tìm vò nguồn","t":"Ngươi đi cùng người gánh hàng ngược về kho cũ và tìm ra chiếc vò rạn. Khi mang tin về, người làng đã phải chuyển chỗ ngủ vì vệt mới xuất hiện ở vách.","e":{"xp":4,"res":1,"danh":-3}}]},{"ma":"S08","ten":"Cổ mẫu","text":["Bên dưới khay đựng thức nuôi có một ổ đất mềm. Mỗi khi cổ mẫu cựa, lũ cổ trong những vò gần đó đều bám về phía ấy.","Người coi trại muốn đem ổ sang lò nuôi riêng. Bà giữ nhà bên cạnh xin ngươi dời cả dãy vò đi trước khi trẻ nhỏ về ngủ."],"c":[{"l":"Dời ổ ra khỏi khu nhà","t":"Ngươi chuyển ổ tới lán cách xa chỗ ngủ, đem vò theo để khỏi tản cổ. Đến tối, bà giữ nhà mới mở lại cửa sổ phía trại.","e":{"hd":[1,0],"danh":3,"res":-1}},{"l":"Giữ cổ mẫu trong trại","t":"Ngươi nhận chỗ lò nuôi và khóa dãy vò quanh ổ. Người nhà bên dời giường sang gian trước, còn phần linh thạch dành nuôi phải trích riêng từ mỗi chuyến.","e":{"res":3,"st":-2,"hd":[0,1]}}]},{"ma":"S09","ten":"Cổ sư đối đầu","text":["Một cổ sư đặt vò của mình trên cầu ván rồi chặn lối ngươi. Vết bò trên nắp giống hệt dấu cổ vừa được tháo cho nhà ở bến.","Họ muốn phân hơn thua bằng cách thả cổ xuống cùng một khay. Người lái đò đứng sau ngươi hỏi bao giờ mới có thể đưa khách qua."],"c":[{"l":"Dời cuộc thử khỏi cầu","t":"Ngươi mang khay ra bãi đất trống để đò được cập bến. Trên khay, cổ của đối phương bò thẳng về chiếc nắp ngươi mang theo.","e":{"xp":4,"hp":"-8%"}},{"l":"Đem dấu tới người bị hạ","t":"Ngươi đậy vò, mời người kia đi cùng tới nhà ở bến. Họ bỏ đi giữa chừng, nhưng người bị hạ đã nhận được bản dập để tự đối.","e":{"hd":[3,0],"danh":3}}]},{"ma":"S10","ten":"Bị quan phủ truy","text":["Cáo thị ngoài bến vẽ cả dáng chiếc vò ngươi mang. Người bán rau nhận ra đường dây buộc, kéo thúng vào trong cho lính đi qua.","Trong tay ngươi có giấy nhà từng thuê giải cổ. Tên người đã hạ cổ lại nằm ở mặt sau, nơi người nhà từng xin ngươi đừng đọc lớn."],"c":[{"l":"Ra trình giấy giải cổ","t":"Ngươi tới nha môn và để người bị hạ tự đọc phần họ chịu xác nhận. Quan sai tạm giữ vò, còn giấy có tên người tố được gấp lại trước mặt họ.","e":{"res":-2,"danh":5,"hd":[1,0]}},{"l":"Rời bến cùng chiếc vò","t":"Ngươi bỏ lại gánh đồ và đi theo lối bờ ruộng. Tới chợ khác, khách thấy cáo thị trước khi thấy vò nên chẳng ai dám mời ngươi vào nhà.","e":{"danh":-5,"tamma":3,"res":1}}]},{"ma":"S11","ten":"Cổ hóa người","text":["Sau tấm rèm là dáng một người đang ngồi chải tóc. Chiếc lược đi qua gáy rồi trở về đúng chỗ cũ, chẳng kéo theo một sợi nào.","Vò của ngươi đã trống, và người ngồi sau rèm quay mặt mỗi khi khay linh thạch dịch gần. Người coi trại hỏi có được phép mở cửa cho họ đi không."],"c":[{"l":"Đóng cửa và quan sát","t":"Ngươi dời khay ra xa rồi ngồi canh ngoài rèm. Khi tới khuya, dáng người đã tan, còn cổ nằm co dưới chiếc lược.","e":{"tv":4,"tamma":2}},{"l":"Đưa khay ra sân trống","t":"Ngươi mang khay ra sân và để người coi trại đứng ngoài then. Dáng ấy theo tới ngạch cửa rồi hụt xuống đất, để lại chiếc lược nằm ngang trên bậc.","e":{"tamma":-2,"res":-1}}]},{"ma":"S12","ten":"Cổ thần","text":["Người nuôi cổ đem vò đến sân, đặt nắp hướng về ghế của ngươi. Chưa ai gõ hiệu, những tiếng cào đã lắng theo nhịp tay ngươi đặt xuống.","Bên cạnh ghế là sổ thức nuôi và những lời xin giải cổ. Người mới đến chờ xem ngươi sẽ truyền cách giải trước hay giữ cả phép trong trại."],"c":[{"l":"Mở sổ giải cổ","t":"Ngươi đặt bản giải cạnh sổ thức nuôi để người đến học tự chép. Khi có nhà mang bệnh nhân tới, người học đứng ra giải trước mặt ngươi.","e":{"hd":[3,0],"danh":8,"xp":5}},{"l":"Giữ phép dưới ấn trại","t":"Ngươi nhận các vò về cùng một kho và chỉ giao nắp cho người đã thề theo. Từ đó, nhà muốn giải cổ phải chờ bản có dấu từ sân của ngươi.","e":{"res":3,"st":3,"hd":[0,3]}}]}],"ket":{"K01":{"ten":"Cổ thần","canh":["Trong sân, các vò cùng im khi ngươi nhấc tay. Người giữ sổ vẫn hỏi ngươi phần linh thạch dành nuôi kỳ tới, và ngươi đẩy hòm về phía họ.","Ngoài hiên có người tới học gõ hiệu. Ngươi giao cho họ chiếc vò đã mẻ miệng, để họ biết nó được giữ kín bằng cách nào."]},"K02":{"ten":"Bị cổ ăn mòn","canh":["Ngươi lật nắp vò trống, còn tay kia không chịu rời cổ tay đã sưng. Tiếng cào ngươi vẫn nghe mỗi tối giờ vọng ngay dưới vạt áo.","Người giữ trại cất chiếc vò khỏi chỗ nằm. Trên ván chỉ còn dấu tròn của đáy vò và túi linh thạch đã cạn."]},"K03":{"ten":"Thầy giải cổ được kính","canh":["Ngươi đặt bát thu cổ ngoài hiên, ở chỗ bệnh nhân có thể tự nhìn. Người nhà tới trả công mang theo chiếc ghế thấp để người đến sau khỏi ngồi đất.","Về sau, có người gọi ngươi tới nhà chỉ để xem lại nơi họ cất chăn. Trong góc ấy, họ đã tự giữ được vò thuốc kín và khô."]},"K04":{"ten":"Gieo dịch cổ diệt thành","canh":["Cửa thành đóng sớm, nhưng vệt cổ vẫn chạy qua kẽ những thúng hàng đã bỏ lại. Tới lúc bếp cuối cùng tắt, ngoài đê còn người dùng tiếng gõ để gọi nhau.","Ngươi đi ngang tấm biển hàng đã tháo xuống khỏi cửa. Ngày giao hàng vẫn còn viết trên mặt gỗ, ngay nơi có vệt cổ bò xuyên qua."]}}},"TU18":{"ten":"Thi tu","sk":[{"ma":"S01","ten":"Xác đầu tiên","text":["Ở rìa {LOC14}, người trông bãi đặt xác vô chủ trên tấm phên. Dưới cổ tay còn buộc mảnh chỉ màu, nhưng sổ tìm người chưa có ai đến nhận.","Ngươi mang theo đồ để luyện thi. Người trông bãi gõ lên nắp hòm và hỏi có nên để lại dấu cho người tới sau không."],"c":[{"l":"Giữ dấu trước khi luyện","t":"Ngươi vẽ dấu sợi chỉ vào sổ rồi đem thi thể đi luyện. Khi xác đã đứng được, người giữ bãi vẫn biết phải chỉ cho gia quyến tìm ở đâu.","e":{"res":2,"xp":3,"hd":[0,1]}},{"l":"Khâm liệm và đợi người nhận","t":"Ngươi thay phên bằng tấm chiếu khô rồi đặt thi thể vào hòm. Đến sáng có người hỏi về sợi chỉ, và tấm phên luyện của ngươi vẫn để trống.","e":{"deed":"an_tang","res":-1}}]},{"ma":"S02","ten":"Đào nhầm mộ người quen","text":["Đất trên nấm mộ vừa lở, bia đã nằm sấp. Tới lúc mở được hòm, ngươi mới nhận ra vết khâu trên chiếc áo mình từng mượn.","Mưa đang dồn vào hố, còn người đào thuê đã buông xẻng. Họ chờ ngươi quyết có lấy thi thể ra khỏi hòm không."],"c":[{"l":"Đóng hòm và dựng lại bia","t":"Ngươi giữ áo nguyên nếp rồi đóng hòm, nhờ người đào thuê chèn đất quanh chân bia. Trước khi về, ngươi tự đọc lại tên trên đá cho họ nghe.","e":{"deed":"an_tang","tamma":-2}},{"l":"Đưa hòm về lán, tìm gia quyến","t":"Ngươi dời hòm khỏi chỗ sụt và gửi tin tới người nhà. Trong lúc đợi, ngươi phải dọn chỗ luyện thi sang mái khác để giữ nguyên chiếc áo và đồ chôn.","e":{"st":-1,"hd":[1,0],"danh":2}}]},{"ma":"S03","ten":"Thi biến","text":["Xác luyện đã đứng lên khi ngươi còn đang tra then. Nó kéo chiếc ghế thấp ra khỏi bóng đèn và đứng chắn lối vào.","Người giúp việc gọi từ bên cửa sau. Trên bàn có vật phát hiệu, nhưng muốn lấy phải bước qua chỗ ghế vừa đổ."],"c":[{"l":"Kéo người giúp việc ra sau","t":"Ngươi chạy vòng qua vách và đưa người giúp việc ra sân. Khi dám quay lại, xác vẫn trong lán, nhưng chiếc hòm đã bật nắp.","e":{"res":-1,"hd":[1,0]}},{"l":"Lấy vật phát hiệu, ghìm xác","t":"Ngươi với được vật phát hiệu và buộc xác dừng bên bàn. Người giúp việc tự mở cửa thoát, bỏ lại gánh đồ đã gãy quai.","e":{"res":1,"xp":3,"hp":"-8%"}}]},{"ma":"S04","ten":"Đạo sĩ Lôi pháp truy đuổi","text":["Đạo sĩ bám theo vệt đất ẩm của thi luyện tới tận mái trạm. Lá phù trên tay họ đã cháy quăn mép.","Dưới mái còn có người dắt ngựa tránh mưa. Ngươi có thể dời cuộc đuổi ra bãi trống hoặc tự giao vật giữ hiệu lệnh."],"c":[{"l":"Dẫn thi luyện ra ngoài trạm","t":"Ngươi gọi xác theo mình ra bãi, để người đi đường lùa ngựa vào trong. Đạo sĩ phóng lôi vào thi luyện, và ngươi mất chỗ nấp sau khi nó đổ xuống.","e":{"res":-2,"hp":"-10%"}},{"l":"Đặt vật phát hiệu dưới mái","t":"Ngươi để vật giữ hiệu lên ghế rồi lùi lại cho đạo sĩ tới lấy. Họ thu xác và để người dắt ngựa rời đi trước khi hỏi tới ngươi.","e":{"res":-3,"danh":3}}]},{"ma":"S05","ten":"Thi luyện từ người thân","text":["Ngươi trải áo liệm lên bàn rồi thấy ngay đường vá ở khuỷu. Người nhà bảo nên để chiếc áo ấy đi theo người chết vì trời đã trở rét.","Phần dụng cụ luyện vẫn nằm dưới gầm bàn. Chỉ cần ngươi nhấc tấm áo lên, nhà sẽ biết ngươi đã chọn cách nào."],"c":[{"l":"Khâm liệm theo lời nhà","t":"Ngươi vuốt phẳng nếp áo rồi khép hòm. Tới ngày giỗ, chiếc bàn được dùng lại để dọn cơm, còn đồ luyện vẫn cất dưới gầm.","e":{"deed":"an_tang","tamma":-3}},{"l":"Đưa thi thể vào luyện","t":"Ngươi đem thi thể đi luyện và giữ lại chiếc áo đã vá. Khi xác đứng trước cửa nhà theo hiệu lệnh, người thân nhận ra áo mà vẫn phải hỏi ai đã đưa nó tới.","e":{"res":3,"tamma":6,"hd":[0,3]}}]},{"ma":"S06","ten":"Làng bị thi triều","text":["Ban đầu người trong làng tưởng tiếng kéo dưới bậc là củi lũ đẩy vào. Đến khi cửa rung, ngươi thấy ngoài sân đã có xác lang thang dồn về phía đèn.","Phía sau dãy nhà còn lối qua bờ ruộng. Người gác muốn mở lối ngay, còn người chưa tìm thấy thân nhân vẫn nắm chặt then cổng."],"c":[{"l":"Dẫn người sống ra bờ ruộng","t":"Ngươi dắt người đi chậm qua cửa sau trước khi tắt đèn. Dân làng ra được bờ ruộng, nhưng sáng hôm sau phải trở về tìm lại đồ và người còn mất dấu.","e":{"deed":"cuu_nguoi"}},{"l":"Kéo thi triều về sân trống","t":"Ngươi dời đèn sang sân phơi để giữ lối ra. Xác dồn về phía ngươi, và tới lúc dân qua hết, sân đã nát ván.","e":{"res":2,"hp":"-10%","danh":3}}]},{"ma":"S07","ten":"Cổ thi trong lăng","text":["Trong lăng, ngươi thấy bát gỗ còn nằm cạnh hòm, mặt trong có vết muỗng mòn. Thi thể không mục, chỉ có tà áo dính vào mép gỗ.","Ở bậc dưới, người dẫn đường hỏi ngươi sẽ đem xác đi hay ghi lại chỗ tìm được rồi đóng cửa. Sương bắt đầu đọng phía trong phiến đá chắn."],"c":[{"l":"Khép lăng và chép dấu","t":"Ngươi vẽ dấu trên ván hòm rồi kê phiến đá về chỗ cũ. Người dẫn đường giữ bản chép để sau này người có thân phận phù hợp tự tới hỏi.","e":{"hd":[1,0],"tv":3}},{"l":"Đưa cổ thi ra luyện","t":"Ngươi nhấc cổ thi khỏi hòm và đem qua cửa đá. Tới khi luyện xong, nó giữ thế rất vững, nhưng người dẫn đường đã bỏ đi cùng lối trở lại lăng.","e":{"deed":"dao_mo","res":3,"xp":4}}]},{"ma":"S08","ten":"Mặt trời đổ lửa","text":["Nắng phủ kín bãi, làm tay nắm cửa nóng tới mức không giữ lâu được. Thi luyện ngoài sân đứng chậm dần, tà áo khô cứng quanh vai.","Có mái che ở đầu dốc, nhưng dân đi đường đã ngồi chen dưới đó. Ngươi còn chiếc xe phủ bạt, vốn để chở đồ về lán."],"c":[{"l":"Chở thi luyện về lán","t":"Ngươi trải bạt kín xe rồi kéo xác về theo đoạn dốc dài. Tới nhà, đồ nghề phải bỏ lại ngoài đường, còn thi luyện đứng được khi trời dịu.","e":{"res":1,"st":-1}},{"l":"Cất hiệu lệnh và chờ qua nắng","t":"Ngươi đưa tay khỏi vật phát hiệu, ngồi lại với người tránh nắng. Tới chiều, xác đã đổ ngoài bãi, chỉ còn chiếc áo có thể đem về.","e":{"res":-2,"tamma":-2}}]},{"ma":"S09","ten":"Thi tỉnh trí","text":["Thi luyện đang gấp tấm khăn trên bàn theo nếp rất đều. Nó ngẩng đầu khi ngươi gọi, rồi nhấc tay lên trước cả lúc hiệu lệnh được phát.","Người giúp việc tưởng người chết đã trở lại, mang chén cũ tới gần. Thi luyện đặt khăn xuống và chậm rãi chạm vào miệng chén."],"c":[{"l":"Dừng hiệu lệnh để quan sát","t":"Ngươi giữ người giúp việc ở ngoài vạch rồi để xác tiếp tục động tác. Nó gấp lại khăn suốt buổi, nhưng chẳng đáp được khi người kia gọi tên.","e":{"tv":4,"tamma":3}},{"l":"Kết thúc phép luyện","t":"Ngươi thu vật phát hiệu rồi tháo phép khỏi thi thể. Người giúp việc cất chén vào hòm, để tấm khăn gấp nguyên cho lễ liệm.","e":{"deed":"an_tang","res":-2}}]},{"ma":"S10","ten":"Bị tông chính vây","text":["Người của tông chính dựng đèn quanh lán, soi rõ các vết chân trên đất. Họ gọi ngươi ra và hỏi tên những thi thể đang bị giữ trong nhà.","Bên trong còn có người chép sổ giúp ngươi. Họ biết một cửa sau, nhưng nếu chạy đi thì sổ nguồn gốc từng xác sẽ nằm lại."],"c":[{"l":"Giao sổ và cho người ra","t":"Ngươi đẩy sổ qua ngưỡng cửa trước, rồi để người chép theo sau. Người ngoài giữ lán, nhưng gia đình có thể tra đúng những thi thể đã bị đưa tới.","e":{"res":-3,"danh":5,"hd":[1,0]}},{"l":"Rút cùng người chép","t":"Ngươi đưa người chép qua cửa sau và mang theo bản tên còn đọc được. Lán bị niêm, và họ phải giữ bản ấy để về sau còn đối với hòm nào thuộc về ai.","e":{"danh":-4,"res":-1,"xp":3}}]},{"ma":"S11","ten":"Thi vương mộ","text":["Trên bậc xuống mộ, nước nhỏ qua một vòng sắt đã gỉ. Mỗi lần nước đụng vòng, các xác luyện theo ngươi lại xoay đầu về phía hòm lớn.","Dưới chân hòm còn thấy một hàng dấu giống nét khắc trên vật phát hiệu. Người đi cùng đề nghị chép chúng và lên ngay trước khi nước dâng."],"c":[{"l":"Chép dấu rồi rời mộ","t":"Ngươi áp giấy lên chân hòm, lấy được dấu trước khi dòng nước che kín. Khi quay lên, thi luyện cũng dừng xoay đầu và đi theo ngươi.","e":{"tv":4,"res":1}},{"l":"Ở lại thử điều khiển","t":"Ngươi đặt vật phát hiệu cạnh chân hòm và chờ. Xác quanh ngươi cùng bước tới khiến người đi cùng phải bỏ dây, còn bản khắc chỉ chép được một phần.","e":{"res":3,"tamma":5,"xp":4}}]},{"ma":"S12","ten":"Ngàn xác một đêm","text":["Đêm chưa hết mà đường vào bãi đã kín bóng người chết. Dưới chân họ, chiếc guốc ai bỏ lại bị kéo lê qua từng rãnh nước.","Ngươi đứng cạnh lối tắt dẫn về nhà dân. Người trông bãi nắm đèn, đợi xem ngươi sẽ giữ lối ấy hay tập hợp thi binh về phía mình."],"c":[{"l":"Giữ lối về nhà dân","t":"Ngươi cùng người giữ bãi dẫn những xác đi lẻ quay về vùng đất trống. Khi trời sáng, đèn đã cạn dầu mà cửa nhà dân vẫn mở được.","e":{"deed":"cuu_nguoi","res":-2}},{"l":"Tập hợp xác dưới hiệu lệnh","t":"Ngươi gọi thi binh về bãi, để chúng đứng thành hàng cạnh vật phát hiệu. Người trông bãi buộc phải dời đèn khỏi đường cũ vì chẳng còn khoảng trống cho người qua.","e":{"res":4,"hd":[0,3],"danh":-5}}]}],"ket":{"K01":{"ten":"Thi vương","canh":["Ngươi hạ tay, cả hàng thi luyện đứng yên trên đất lầy. Người coi bãi vẫn đi dọc hàng, dò từng mảnh thẻ để biết xác nào còn người tìm.","Trong lán, những gia đình mang chiếu đến nhận thi thể chờ qua hết phiên. Sau khi họ đi, ngươi gấp phần chiếu còn lại và dọn chỗ cho hòm kế."]},"K02":{"ten":"Bị chính thi phản","canh":["Hiệu lệnh đã dứt, xác luyện vẫn đẩy ghế từng chút về phía ngươi. Khi người giữ bãi chạy tới, chiếc ghế nằm nghiêng và vật phát hiệu đã vỡ.","Sáng sau, họ nhặt thẻ tên đặt cạnh ngươi rồi khóa cửa lán. Tiếng kéo ngoài sân đã im, còn chỗ cắm then lành lặn từ phía ngoài."]},"K03":{"ten":"Bị Lôi pháp tru diệt","canh":["Sét rơi ngoài bãi, soi bàn tay ngươi vẫn giữ vật phát hiệu đã cháy đen. Thi luyện đổ xuống cùng lúc, và người ở trạm không còn nghe ngươi đáp.","Đạo sĩ để lại chiếu khô trước khi đi. Người trông bãi dùng chiếu ấy phủ chỗ ngươi nằm rồi nhặt từng thẻ còn đọc được."]},"K04":{"ten":"Tự chôn mình làm thi","canh":["Ngươi xuống hòm và kéo nắp lại tới chỗ vạch đã đánh dấu. Ngoài miệng hố, người ngươi nhờ đứng đợi cho đến khi không còn tiếng gõ.","Qua mùa mưa, người trông bãi vẫn trông thấy đất sụt quanh nấm mộ ấy. Họ đắp đất lên, lật tấm bia quay về phía đường để người qua biết chỗ mà tránh."]}}},"TU19":{"ten":"Phật tu","sk":[{"ma":"S01","ten":"Xuống tóc","text":["Ngươi ngồi trên ghế nhỏ ở {LOC12}, gáy chạm luồng gió từ cửa. Người cầm dao đặt bên chân ngươi tấm khăn để hứng tóc.","Ngoài hiên, người thân giữ tay nải vẫn chưa chịu về. Thầy hỏi ngươi muốn xuống tóc ngay hay ra ngồi với họ cho đến khi họ nói hết."],"c":[{"l":"Xuống tóc trước thềm","t":"Ngươi cúi đầu, nghe từng lọn tóc rơi xuống khăn. Khi ra hiên, người nhà đã đi, nhưng tay nải vẫn được kê lên chỗ khô.","e":{"tv":3,"res":1,"tamma":-3}},{"l":"Ra gặp người nhà trước","t":"Ngươi ra ngồi cạnh người thân và nghe họ dặn cách đi qua mùa rét. Khi quay vào, thầy đã hâm lại bát nước để rửa dao.","e":{"mp":"10%","danh":2}}]},{"ma":"S02","ten":"Hóa duyên bị đuổi","text":["Chủ nhà ở cuối chợ lấy cán chổi chặn ngang ngưỡng cửa. Sau lưng ông có tiếng gạo vét từ đáy chum.","Ngươi nghe một đứa nhỏ xin thêm cơm trong nhà. Bát khất thực trong tay ngươi còn trống, và gió đã bắt đầu thổi lạnh qua phố."],"c":[{"l":"Xin việc đổi bữa","t":"Ngươi đặt bát xuống và xin gánh nước. Chủ nhà chừa cho ngươi phần cháo bám quanh thành nồi sau khi cả nhà ăn.","e":{"hp":"-5%","res":1}},{"l":"Chào rồi sang ngõ khác","t":"Ngươi rời cửa, để chủ nhà quét nốt sân. Đến tối, người hàng xóm chia chỗ khô dưới mái nhưng cũng chỉ có nước ấm.","e":{"tv":2}}]},{"ma":"S03","ten":"Siêu độ làng chết dịch","text":["Mưa làm nhòe tờ giấy ghi người chết dán ở đầu làng. Ngươi thấy dưới mỗi mái nhà đều còn chiếc bát úp bên cửa.","Người sống xin ngươi tụng trước khi đem đồ đi chôn. Người giữ sổ muốn đọc từng tên, còn một nhà chỉ xin được ngồi yên bên chiếc bát."],"c":[{"l":"Đọc tên cùng người giữ sổ","t":"Ngươi chờ ông hong khô giấy rồi đọc tên theo từng mái nhà. Tới chỗ chữ đã nhòe, gia quyến tự nói phần còn thiếu.","e":{"deed":"sieu_do","res":1}},{"l":"Ngồi cạnh các nhà muốn im lặng","t":"Ngươi tụng nhỏ ở sân và chừa hiên cho họ ngồi. Lúc trời tạnh, họ tự mang bát ra, đặt cạnh tấm chiếu đã hong.","e":{"tamma":-3,"res":1,"danh":3}}]},{"ma":"S04","ten":"Phá giới cứu người","text":["Một kẻ có đao đẩy người bán dầu sát chân tường. Ngọn đèn rơi nhưng chưa tắt, soi đúng bàn tay người ấy đang níu cửa.","Ngươi đứng đủ gần để ra đòn. Sau lưng người cầm đao còn một khe hẹp mà người bán dầu có thể lách qua nếu ngươi giữ được hắn."],"c":[{"l":"Chặn tay đao, mở đường thoát","t":"Ngươi ghì cổ tay cầm đao và gọi người bán dầu chạy qua khe. Hắn giằng ra làm vai ngươi rách áo, nhưng người kia đã tới được đầu phố.","e":{"wound":"ngoai","deed":"cuu_nguoi"}},{"l":"Ra đòn đoạt mạng","t":"Ngươi đánh để người bán dầu thoát và kẻ cầm đao ngã chết bên tường. Khi ngươi đưa tay đỡ ngọn đèn, Phật quang đã tắt và nguyện lực tiêu tan.","e":{"deed":"giet_cuop_dang_ac"}}]},{"ma":"S05","ten":"Ma đầu xin quy y","text":["Người tới xin quy y đặt thanh đao còn bọc vải xuống thềm. Sau lưng họ là thân nhân của một người đã chết, tay vẫn cầm tờ đơn cũ.","Họ xin ở lại qua đêm và chấp nhận nghe lời người đang đợi. Chỗ ngủ trong chùa còn, nhưng tấm chiếu ngoài cổng cũng chưa ai dọn."],"c":[{"l":"Cho trú và giữ cuộc gặp","t":"Ngươi cất đao, dành chỗ ngủ rồi hỏi người cầm đơn có muốn ngồi lại sáng mai. Họ chưa nhận lời, nhưng tự chọn mang tờ đơn về hay để lại.","e":{"res":1,"tamma":2,"hd":[3,0]}},{"l":"Dẫn họ ra trình diện","t":"Ngươi đi cùng họ tới cửa quan, mang theo thanh đao còn bọc. Người cầm đơn giữ bản của mình và tự chọn ngày tới nói.","e":{"danh":4,"hd":[1,0]}}]},{"ma":"S06","ten":"Sư phụ viên tịch","text":["Sư phụ vừa tắt thở khi ấm nước trong phòng còn sôi. Người học nhỏ tuổi nhất vẫn đứng ngoài hiên, cầm chiếc chén thầy thường dùng.","Trong hòm có bản kinh thầy chưa chép xong. Có người xin ngươi đọc nốt ngay, còn người giữ bếp muốn thu dọn giường trước khi khách tới."],"c":[{"l":"Đọc bản kinh còn dở","t":"Ngươi đọc tới dòng cuối rồi dừng ở chỗ mực chưa kín. Người học nhỏ đặt chiếc chén bên trang ấy và đọc tiếp phần mình đã thuộc.","e":{"tv":5,"xp":4}},{"l":"Cùng dọn chỗ nằm của thầy","t":"Ngươi hạ màn và gấp chiếc chăn với người giữ bếp. Người học nhỏ mang chén vào rửa, rồi xin tự đọc bản kinh vào buổi sau.","e":{"tamma":-4,"res":1}}]},{"ma":"S07","ten":"Chùa bị ma tông đốt","text":["Lửa đã bén mái kho ở {LOC12}. Người trú kéo chăn ra sân, còn từ lối sau có tiếng ai gọi vì cửa đã kẹt.","Trong thư khố vẫn còn giấy ghi nơi các gia đình tản đi. Ngươi phải chọn lối tới cửa kẹt hoặc cứu phần giấy trước khi xà sụm."],"c":[{"l":"Phá cửa sau để đưa người ra","t":"Ngươi cùng người giữ sân nhấc cửa khỏi ngạch. Người mắc kẹt thoát được, còn sáng hôm sau các nhà phải tự đi hỏi lại địa chỉ của nhau.","e":{"deed":"cuu_nguoi","hp":"-5%"}},{"l":"Chuyền hòm giấy ra sân","t":"Ngươi đưa hòm cho người đứng ngoài rồi gọi họ mở lối sau từ phía sân. Người cuối thoát sát lúc xà đổ, chân bỏng vì phải đợi.","e":{"danh":4,"tamma":3}}]},{"ma":"S08","ten":"Thiền trăm ngày","text":["Bụi ở bậu cửa dày thêm từ buổi ngươi bắt đầu ngồi thiền. Có người quen đặt nước xuống mỗi sáng, nay chỉ còn nghe tiếng bát cọ lên đá.","Hôm nay họ gõ cửa và nói người gánh nước đã ngã ở dốc. Chuông chưa báo hết buổi, còn ngoài hiên đã có tiếng kéo cáng."],"c":[{"l":"Rời chiếu xuống dốc","t":"Ngươi bước ra khi chân còn tê, cùng họ khiêng người ngã lên hiên. Chiếu thiền để trống đến tối, rồi được dùng lót dưới chiếc cáng.","e":{"hd":[3,0],"res":1,"tv":-2}},{"l":"Nhờ người đi, ngồi hết buổi","t":"Ngươi gọi người ngoài cửa tới giúp và ở lại đến khi chuông dứt. Lúc ra sân, người bị thương đã được cáng về, còn chiếc bát sáng vẫn chưa có ai mang đi.","e":{"tv":6,"tamma":3}}]},{"ma":"S09","ten":"Người tình cũ tìm tới","text":["Người ấy đứng trước chùa, cầm áo ngươi từng bỏ lại. Mép tay áo đã được vá bằng thứ chỉ quen dùng ở nhà cũ.","Họ cần người đi cùng qua đoạn đường ngập để về đưa mẹ đi chữa. Trước khi quay xuống dốc, họ hỏi ngươi có muốn nghe chuyện trong nhà không."],"c":[{"l":"Đi cùng qua đoạn nước","t":"Ngươi xắn áo, theo họ qua chỗ nước xiết. Sang bờ, họ đưa áo cũ cho ngươi giữ và nói hết chuyện đã định kể.","e":{"tamma":4,"hp":"-5%","hd":[1,0]}},{"l":"Mời họ nghỉ và tìm người dẫn","t":"Ngươi dọn chỗ cho họ hong dép rồi tìm người quen đường ngập. Khi khởi hành, họ giữ lại áo cũ, hẹn lúc mẹ khỏe sẽ mang sang.","e":{"tamma":-2,"res":1}}]},{"ma":"S10","ten":"Độ hóa yêu","text":["Sau vách kho có con yêu đang gỡ mảnh lưới khỏi móng. Nó đặt từng sợi xuống nền, cạnh những hạt thóc đã cắn dở.","Người coi kho mang đèn tới và đòi đóng cửa lại. Con yêu nhìn ngươi, rồi đẩy trả cái đấu còn dính trấu."],"c":[{"l":"Dẫn nó ra ngoài và nghe chuyện","t":"Ngươi mở cửa bên hông rồi cho nó tự bước ra. Nó chỉ chỗ thóc bị rơi trên đường, còn người coi kho đi theo để xem có đúng không.","e":{"res":2,"hd":[3,0]}},{"l":"Để hai bên tự định phần bù","t":"Ngươi giữ đèn trong tay và nghe người coi kho kê thóc đã mất. Con yêu nhận kéo bao để trả phần ấy, bắt đầu bằng bao còn mắc dưới cầu.","e":{"danh":3,"res":1}}]},{"ma":"S11","ten":"Xá lợi","text":["Sau lễ hỏa táng, người quét sân tìm thấy hạt sáng trong một lớp tro nguội. Họ đặt nó lên đĩa bên chiếc lược của người đã khuất.","Khách đứng ngoài xin đem đi thờ, còn người nhà chỉ muốn giữ chiếc lược. Người giữ chùa đợi ngươi hỏi ý họ trước khi niêm đĩa."],"c":[{"l":"Đặt xá lợi dưới mái chung","t":"Ngươi đợi người nhà chọn xong rồi đặt đĩa ở chỗ khách có thể đến viếng. Họ đem lược về, còn người giữ chùa ghi rõ tên bên đĩa.","e":{"res":2,"danh":3}},{"l":"Giao xá lợi cho người nhà","t":"Ngươi bọc hạt sáng cùng chiếc lược và trao cho người nhà. Họ xin người giữ chùa chỉ đưa khách tới khi trong nhà đã thắp đèn.","e":{"tamma":-3,"hd":[1,0]}}]},{"ma":"S12","ten":"Ngộ không","text":["Ngươi ngồi trước bát nước đã nguội. Bóng ngọn đèn trong bát cứ lệch đi, dù ngươi đã thôi chạm vào bàn.","Ngoài sân, người giữ bếp gọi tìm ai phụ đỡ thúng. Trước mặt ngươi, vệt sáng trong nước vẫn lay như có điều chưa chịu dứt."],"c":[{"l":"Ở lại nhìn mặt nước lặng","t":"Ngươi chờ tới khi nước phẳng rồi nhấc bát khỏi bàn. Dưới đáy chỉ còn vết xước quen tay, nhưng suốt lúc ấy ngươi thấy như đã từng nhìn nó.","e":{"tv":6,"tamma":-5}},{"l":"Đặt bát xuống và ra phụ","t":"Ngươi ra sân đỡ thúng, để mặt nước tự lặng. Lúc quay vào, người giữ bếp đã dùng chiếc bát ấy kê chân bàn khỏi cập kênh.","e":{"res":2,"hd":[1,0],"mp":"15%"}}]}],"ket":{"K01":{"ten":"Thành Phật","canh":["Ngươi đi qua sân khi người giữ bếp đang nhóm lửa. Phật quang vừa lên, người đứng gần chỉ thấy đủ sáng để tìm nắp nồi đã lăn dưới bàn.","Khách muốn ở lại nghe chuyện, còn ngươi xếp thêm chiếu cho người đến trễ. Tới lúc bếp nguội, họ tự gấp chiếu rồi mang tro ra vườn."]},"K02":{"ten":"Phá giới hoàn tục","canh":["Ngươi gấp áo tu bên cửa, nơi người giữ bếp vẫn để bát nước. Phật quang chưa trở lại, và người nhà đứng ở sân với chiếc áo đi đường.","Ra khỏi cổng, ngươi ghé giúp họ buộc lại gánh. Lưỡi dao cạo được để lại, còn vết rách trên tay áo do chính ngươi khâu."]},"K03":{"ten":"Viên tịch để lại xá lợi","canh":["Người học trò ngồi bên ngươi tới lúc đèn cạn dầu. Khi nhấc bát khỏi đầu giường, họ lau sạch phần nước đã đổ xuống tấm ván.","Sau lễ hỏa táng, hạt xá lợi được đặt cạnh bát. Người tới viếng vẫn dùng cửa bên để người trong chùa có thể đưa cơm qua sân."]},"K04":{"ten":"Tỉnh mộng (Mộng Ấn)","canh":["Ngươi nghe chuông và thấy mảnh mộng hiện lên trong mặt nước. Cánh cửa ở đó hé vừa đủ cho một vệt sáng lạnh lọt ra.","Khi chuông dứt, sân chùa đã sáng, và người giữ bếp mang nước tới. Ngươi nhận bát, vẫn còn cảm giác bàn tay mình từng ấm lên ở chỗ khác."]}}},"TU20":{"ten":"Nho tu","sk":[{"ma":"S01","ten":"Đêm đọc sách thấy chữ phát sáng","text":["Ngươi hong trang sách bên đèn, lấy chiếc thước chặn góc giấy ẩm. Khi ngọn lửa lịm xuống, dòng chữ ngươi vừa đọc vẫn còn sáng.","Ở đầu dòng là lời hẹn trả công cho người chở sách. Phiếu trong tay áo của ngươi cho thấy lời ấy vẫn chưa làm trọn."],"c":[{"l":"Đem công tới trả trước khi đọc tiếp","t":"Ngươi gấp trang giấy, ra ngõ tìm người chở. Lúc trở về, chữ đã thôi sáng, nhưng ngươi đọc liền mạch được chỗ trước đó vẫn vấp.","e":{"hd":[1,0],"tv":3}},{"l":"Chép lại dòng sáng và lưu phiếu","t":"Ngươi chép chữ lên giấy khô rồi kẹp phiếu cạnh đó. Đến sáng, ngươi tìm được người chở đã chuyển nơi ở và phải nhờ người đi đường đưa phần công.","e":{"res":1,"xp":2}}]},{"ma":"S02","ten":"Viết hịch","text":["Người từ làng lên {LOC02} mang theo tờ thu thóc đã thủng mép. Họ đặt tờ ấy cạnh giấy trắng và xin ngươi viết lời để quan phải đọc.","Ngoài cửa có người đề nghị thêm chuyện chưa có ai chứng để lời mạnh hơn. Người đem tờ thu cũ vẫn đứng đợi ngươi hỏi tên."],"c":[{"l":"Viết từ biên nhận đã đối","t":"Ngươi chép đúng ngày và người đã ký, rồi để dân tự đọc lại. Tờ hịch ngắn, nhưng hôm đưa đi có người mang cả sổ tới đứng cạnh.","e":{"res":1,"danh":3}},{"l":"Truyền hịch trước khi đối đủ lời","t":"Ngươi cho chép ngay khi phiên chợ đang đông. Quan mở kho tra phần có giấy, còn người bị ghi oan mang đơn tới tận cửa ngươi.","e":{"danh":5,"hd":[0,1]}}]},{"ma":"S03","ten":"Can vua","text":["Trên bàn ở {LOC02} có chiếu sửa đê và lệnh điều lính. Người giữ ấn đặt tay lên bản lệnh, chờ ngươi nói lý do phải hoãn.","Ngươi vừa tận mắt thấy đất lún dưới chân cọc. Viên coi kho muốn giữ kín chuyện ấy cho tới khi xe đã đi."],"c":[{"l":"Đọc lời dân trước lúc đóng ấn","t":"Ngươi mời người đắp đê vào nói chỗ cọc lún. Người giữ ấn hoãn chuyến, còn viên coi kho phải ngồi lại trả lời trước mặt họ.","e":{"hd":[3,0],"res":1,"danh":3}},{"l":"Xin đi xem đê cùng người giữ ấn","t":"Ngươi gấp tờ can và dẫn người xem qua đoạn đất còn ướt. Chuyến đầu đã rời kho, nhưng người giữ ấn cho gọi lại chuyến sau.","e":{"xp":3,"tv":2}}]},{"ma":"S04","ten":"Đốt sách","text":["Người coi cửa đem danh mục tới và chỉ tên quyển sách trên bàn. Họ đã nhóm lò, đợi ngươi giao đúng bản bị lệnh thu.","Một người học lặng lẽ mở túi vải dưới bàn. Họ chỉ có thể mang đi phần giấy còn khô và hỏi ngươi muốn giữ trang nào."],"c":[{"l":"Gửi bản sao ra ngoài","t":"Ngươi đặt những trang có tên người làm chứng vào túi và để học trò tự chọn lối đi. Bản chính cháy, nhưng về sau từng nhà còn trang để đối.","e":{"res":2,"danh":2}},{"l":"Giữ người học và nộp quyển sách","t":"Ngươi bảo họ đứng nguyên rồi tự trao quyển sách cho người coi cửa. Sau buổi ấy, cả lớp phải viết lại những điều còn thuộc, chừa trống chỗ ai cũng quên.","e":{"res":-1,"tamma":3,"xp":2}}]},{"ma":"S05","ten":"Học trò phản đạo","text":["Ngươi nhận ra nét bút học trò trên tờ xin lấy đất của người đã cho họ ở nhờ. Họ vẫn dùng câu ngươi thường dạy để mở đầu tờ giấy.","Học trò nói chủ mới sẽ trả công và cho họ một ghế trong sổ. Người mất đất chờ ngoài sân, cầm phiếu góp công đã cũ."],"c":[{"l":"Gọi học trò đối mặt người mất đất","t":"Ngươi đặt phiếu cũ cạnh đơn và để người ngoài sân tự kể. Học trò rút chữ ký, nhưng vẫn phải đi cùng họ tới chỗ đã nộp giấy để xin trả đất.","e":{"hd":[3,0],"res":1}},{"l":"Gửi bản đối chiếu đến bàn xét","t":"Ngươi sao riêng nét chữ và phần công đã góp, không ký đỡ cho học trò. Vụ xét mở, còn ghế của họ trong lớp bỏ trống từ buổi sau.","e":{"tamma":3,"danh":3}}]},{"ma":"S06","ten":"Văn tự ngục","text":["Lính gác đem tới một trang sách có câu bị khoanh mực đỏ. Từ cửa ngục, ngươi thấy người sao sách đang bị giữ vì nét chữ trên bản ấy.","Câu bị khoanh do chính ngươi viết. Viên xét chỉ hỏi ai đã chép và để sẵn chỗ cho ngươi ký."],"c":[{"l":"Nhận lời mình đã viết","t":"Ngươi viết tên mình bên câu bị khoanh và đọc hết đoạn cho người xét. Người sao sách được về, còn bản thảo của ngươi bị giữ để tra tiếp.","e":{"res":2,"st":-2}},{"l":"Đòi đối bản trước khi ký","t":"Ngươi chỉ chỗ xuống dòng làm câu bị hiểu khác và xin đưa bản gốc tới. Người sao sách phải chờ thêm, nhưng người xét ghi cả đoạn vào hồ sơ thay vì giữ riêng câu khoanh.","e":{"tamma":2,"xp":3}}]},{"ma":"S07","ten":"Một câu hàng phục sơn tặc","text":["Kẻ cầm gậy đứng chắn xe ở đầu dốc, sau lưng có người kéo chân què. Ngươi thấy tay họ run khi chiếc xe chở gạo dừng lại.","Người hộ tống đã nắm chuôi đao. Ngươi có thể gọi người cầm gậy ra nói chuyện hoặc lấy lời giữ họ đứng yên cho xe lùi."],"c":[{"l":"Gọi họ bỏ gậy và nói giá gạo","t":"Ngươi hỏi ai đang đói và câu nói khiến người cầm gậy buông tay. Người hộ tống chịu mở thúng, ghi phần đưa đi trước mặt họ.","e":{"res":1,"hd":[3,0],"st":-1}},{"l":"Dùng lời giữ chân cho xe lùi","t":"Lời ngươi dằn xuống khiến kẻ cầm gậy khựng lại. Xe lùi khỏi dốc, còn nhóm người phía sau phải tự tìm đường đưa người què về.","e":{"mp":"-10%","xp":3}}]},{"ma":"S08","ten":"Đối đáp với ma tu","text":["Ma tu đặt tờ khế lên bàn, mời ngươi đọc dòng đã viết dưới tên người bị giữ. Họ bảo người ấy đã điểm chỉ nên chẳng còn gì để hỏi.","Ngươi thấy mép giấy có vết bị cắt, còn người đứng bên cửa không dám ngẩng lên. Đối phương chờ ngươi nhận chữ trên khế hay đòi đọc lời người ký."],"c":[{"l":"Để người ký tự đọc điều đã nhận","t":"Ngươi lui khỏi bàn và mời họ nói từ chỗ đứng. Khi nghe phần bị cắt, người giữ cửa đòi xem lại bản của mình trước khi cho mang người đi.","e":{"res":1,"hd":[1,0]}},{"l":"Chỉ ra phần bị cắt ngay trên khế","t":"Ngươi đặt vết cắt cạnh bản chép của người làm chứng và chỉ đường mép không khớp. Ma tu thu khế, để phiên xét hoãn và người bị giữ còn ở nguyên chỗ.","e":{"xp":4,"mp":"-10%"}}]},{"ma":"S09","ten":"Lập học đường","text":["Ngươi kê bàn dưới mái chợ, lấy mảnh ngói chèn cho chân khỏi cập kênh. Người mang trẻ tới muốn biết chúng có thể học sau buổi làm không.","Người góp tiền dựng lớp xin dạy trước cho con nhà họ. Những đứa đang đứng ngoài chỉ có bảng gỗ đã dùng mòn."],"c":[{"l":"Dạy theo giờ rảnh của người học","t":"Ngươi mở lớp sau phiên, tự nhờ người khác giữ đèn. Người góp vốn rút bớt phần hứa, còn lũ trẻ có thể đem bảng tới sau khi dọn hàng.","e":{"hd":[3,0],"res":1,"st":-2}},{"l":"Nhận tiền và dành lượt học riêng","t":"Ngươi lấy tiền sửa mái rồi dành buổi sớm cho nhà góp. Các học trò phải làm việc ban ngày chờ tới khi có người nhận trông lớp tối.","e":{"st":3,"danh":-2}}]},{"ma":"S10","ten":"Sách truyền thiên hạ","text":["Ở {LOC11}, tờ in thử còn dính vào khuôn. Người bồi giấy chỉ một chữ mất nét và bảo nếu in ngay thì phải để nguyên chữ ấy qua cả lô.","Người đặt sách đã hẹn xe ra bến. Một học trò muốn sửa tiếp, còn người coi xưởng hỏi ai sẽ trả tiền giữ thợ ở lại."],"c":[{"l":"Dừng in để sửa chữ","t":"Ngươi chịu phần công thêm rồi đợi học trò so lại trang. Xe đi trước, nhưng khi sách tới tay người đọc, họ không phải nhờ ai đoán chữ đã mất.","e":{"st":-2,"res":2,"danh":4}},{"l":"Gửi bản thử, kèm tờ đính chính","t":"Ngươi đánh dấu trang có lỗi và gửi tờ sửa theo xe. Sách tới đúng hẹn, còn người nhận phải tự dán lại từng bản trước khi cho mượn.","e":{"danh":2,"st":1}}]},{"ma":"S11","ten":"Văn tâm nứt","text":["Ngươi đóng dấu vào tờ khiến một hộ phải chịu khoản không do họ vay. Nét mực chưa khô thì văn tâm rạn, hạo nhiên khí theo đó mà tản.","Người đưa giấy bảo cứ ngồi yên tới khi họ lấy lại khế. Ngoài hiên, người bị ghi nợ vẫn cầm giấy lĩnh thóc chờ ngươi gọi."],"c":[{"l":"Công khai sửa tờ đã ký","t":"Ngươi gọi người ấy vào, đọc lại chỗ mình sửa sai rồi trao bản có dấu mới. Khí đã tản vẫn chưa về, còn người đưa giấy thôi gửi việc tới bàn ngươi.","e":{"res":-2,"tamma":-3,"danh":2}},{"l":"Giữ dấu và theo người đưa giấy","t":"Ngươi để nguyên tờ đang khô và nhận phần công họ trả. Khi thử đọc lời cũ lên, ngươi nghe câu hụt giữa chừng, còn người mang giấy lĩnh thóc bỏ về.","e":{"hd":[0,5],"st":2}}]},{"ma":"S12","ten":"Thánh ngôn","text":["Ngươi vừa mở sổ thì người đứng chật sân đã im. Câu ngươi định đọc là lời hẹn giữ phần công cho những người sắp phải rời chỗ ở.","Người coi sổ xin ngươi nói thay tất cả để kịp đóng ấn. Ngoài cửa có người mới đến, giấy của họ vẫn chưa ghi tên."],"c":[{"l":"Đọc lời hẹn rồi nhường lời cho dân","t":"Ngươi đọc điều đã ký rồi lùi khỏi bàn. Người đến trễ tự nói tên, và người coi sổ phải mở trang mới để chép cho đủ.","e":{"res":3,"danh":6,"hd":[1,0]}},{"l":"Giữ lời đã ký và buộc mở sổ","t":"Lời ngươi làm tay người giữ ấn dừng giữa chừng. Sổ được mở cho đối ngay, nhưng người tới trễ phải giữ tờ riêng vì phiên xét đã khép.","e":{"res":2,"tv":5}}]}],"ket":{"K01":{"ten":"Á thánh","canh":["Ngươi tới lớp lúc người học đang tự sửa một dòng chép sai. Họ đứng dậy, nhưng ngươi kéo ghế tới bên cửa để khỏi che ánh sáng trên bảng.","Khách muốn nghe ngươi nói, còn người học muốn làm xong việc đang dở. Ngươi chờ đến lúc nét cuối khô rồi bảo họ tự đọc trước."]},"K02":{"ten":"Văn tâm vỡ thành phế nhân","canh":["Lời ngươi đọc rơi xuống trong căn phòng kín, không còn sức lay ngọn đèn. Văn tâm đã vỡ, và trang sách cũ chỉ còn nét mực xếp trên giấy.","Ngươi gấp sách rồi lấy chổi quét vụn than cạnh bếp. Người đến xin học được ngươi chỉ sang mái bên, nơi có người vẫn đang đứng lớp."]},"K03":{"ten":"Đế sư","canh":["Người giữ ấn mời ngươi ngồi cạnh bàn xét, ngay chỗ có thể nhìn thấy cả sổ lương và đơn của dân. Ngươi đẩy tờ đã duyệt sang bên để người cầm đơn có thể đặt giấy trước mặt họ.","Đến cuối buổi, người giữ ấn tự hỏi hộ cuối có bản để mang về không. Ngươi thu chiếc thước vẫn để cạnh tay và cho người ngoài mở cửa."]},"K04":{"ten":"Sách truyền đời","canh":["Bản ngươi chép đã sờn góc, nhưng ở lớp xa người đọc vẫn dùng nó để đối bản mới. Họ ghi lời sửa ở mép, giữ đủ nét cũ để người sau còn biết vì sao phải đổi.","Một ngày ngươi ghé qua, người đứng lớp đọc đoạn ấy bằng giọng khác hẳn. Cuối buổi, họ đặt sách xuống và cho học trò tự thử điều vừa đọc."]}}},"TU21":{"ten":"Thiên cơ sư","sk":[{"ma":"S01","ten":"Quẻ đầu","text":["Ở {LOC05}, thẻ quẻ ngã nghiêng về phía chén nước. Trong mặt nước, ngươi thoáng thấy mấy đôi dép dừng trước cầu, rồi nước đục đi.","Người hỏi chỉ muốn biết nên qua cầu hôm nay hay chờ. Khi ngươi với tay dựng thẻ, ngón tay bỗng lạnh dù nước trong chén còn ấm."],"c":[{"l":"Nói điều thấy và điều chưa rõ","t":"Ngươi tả đôi dép và nhắc quẻ không chỉ được ngày. Người ấy chọn hỏi người coi cầu, còn tay ngươi run tới tận khi cất chén.","e":{"res":1,"xp":2,"tamma":-1}},{"l":"Gieo thêm để tìm ngày","t":"Ngươi dốc thẻ lần nữa, nhưng bóng người dời sang bến. Tóc mai bạc thêm, và người hỏi bỏ về khi nghe ngươi không dám hẹn ngày.","e":{"tho":0.5,"res":2}}]},{"ma":"S02","ten":"Quẻ báo chết cho người thân","text":["Trong quẻ, ngươi thấy chiếc bát của người nhà nằm úp bên giường. Tiếng ho phía bên kia cửa vẫn đều, chưa cho biết điều gì sắp tới.","Khi nhấc tay khỏi thẻ, ngươi phải ngồi xuống vì đầu choáng. Người thân mang nước tới, hỏi vì sao ngươi giữ chặt chiếc bát của họ."],"c":[{"l":"Kể dấu quẻ và mời thầy thuốc","t":"Ngươi nói bóng chiếc bát có thể chỉ cơn bệnh rồi nhờ thầy thuốc tới xem. Người nhà vẫn tự chọn có đi chữa, còn ngươi giữ kín điều quẻ chưa nói rõ.","e":{"hd":[1,0],"res":1}},{"l":"Ở lại chăm mà không gieo thêm","t":"Ngươi cất thẻ và đỡ người thân uống nước. Cơn ho chưa dứt, nhưng họ ngủ được trước khi đầu ngươi thôi choáng.","e":{"tamma":-3,"mp":"10%"}}]},{"ma":"S03","ten":"Vua mời xem quốc vận","text":["Ở {LOC02}, người giữ ấn trải bản đồ lên bàn, lấy đĩa cân chặn mép. Ngươi nhìn thấy kho mở trong quẻ, nhưng không biết vì cứu đói hay vì quân kéo tới.","Quẻ vừa dứt, khớp tay ngươi nhức buốt. Người đợi ngoài cửa đã mài mực, sẵn sàng chép lời ngươi vào chiếu."],"c":[{"l":"Đọc các ngả và xin tra kho","t":"Ngươi ghi cả khả năng cứu đói lẫn điều quân rồi xin xem sổ lương. Chiếu chưa đóng dấu, còn ngươi rời bàn với cổ tay phải quấn vải.","e":{"tho":0.5,"st":3}},{"l":"Chỉ nêu dấu chắc mình đã thấy","t":"Ngươi chỉ ghi hình cửa kho mở và từ chối nói kho sẽ mở cho ai. Người giữ ấn gấp giấy lại, không giao phần lễ đã hứa.","e":{"hd":[1,0],"res":1}}]},{"ma":"S04","ten":"Ma đầu ép xem đường sống","text":["Người cầm đao đặt thẻ quẻ trước mặt ngươi và buộc ngươi chỉ lối thoát. Trong quẻ, con đường hiện ra bên vệt nước, nhưng bờ bên kia chìm trong bóng tối.","Cơn lạnh chạy lên cánh tay khi ngươi nhặt thẻ. Sau tấm vách, ngươi nghe người giữ ngựa loay hoay kéo dây khỏi chốt."],"c":[{"l":"Nói rõ rủi ro ở bến","t":"Ngươi chỉ dấu nước và nhắc bờ kia có thể không cập được. Kẻ cầm đao chạy xuống bến, để ngươi với bàn tay cứng lạnh và chiếc ghế đổ.","e":{"mp":"-10%","res":1}},{"l":"Bẻ thẻ, không chỉ lối","t":"Ngươi bẻ thẻ cuối và nói quẻ chưa đủ để dẫn đường. Kẻ ấy tự kéo ngựa đi, còn ngươi phải nhờ người giữ trạm gỡ cửa đã chốt.","e":{"hd":[3,0],"hp":"-5%"}}]},{"ma":"S05","ten":"Thấy bóng mình trong quẻ (Mộng Ấn)","text":["Trong mặt quẻ có bàn tay đang gấp tờ giấy. Ngươi nhìn xuống và thấy tay mình cũng có thói quen miết góc giấy theo chiều ấy.","Cổ tay chợt lạnh, hình trên mặt quẻ bắt đầu loang. Ngươi có thể ghi điều vừa thấy hoặc giữ quẻ mở để xem bàn tay kia viết gì."],"c":[{"l":"Ghi hình rồi khép quẻ","t":"Ngươi vẽ lại nếp gấp và cất tờ giấy. Lúc quay vào, cảm giác quen vẫn còn nhưng ngươi chẳng gọi được một cái tên nào.","e":{"tamma":-2,"tv":3}},{"l":"Giữ quẻ tới khi hình tan","t":"Ngươi giữ tay trên thẻ đến khi cơn lạnh tê tận khuỷu. Giấy trong quẻ lật mặt, để lộ vệt mực chưa thành chữ rồi tan vào nước.","e":{"tho":0.5,"res":2,"tv":5}}]},{"ma":"S06","ten":"Bị thiên khiển","text":["Ngươi chưa kịp thu thẻ thì mắt tối sầm. Tiếng chén vỡ dưới nền đến trước cơn đau buốt trong thức hải.","Có người muốn ngươi gieo tiếp để kịp giờ mở kho. Người giữ phòng đã lấy khăn ấm, đứng đợi ngươi buông tay khỏi quẻ."],"c":[{"l":"Dừng quẻ và dưỡng thương","t":"Ngươi để người giữ phòng cất thẻ rồi dựa lưng tới khi phân biệt được ánh ngoài cửa. Khách đi tìm người khác, còn ngươi bỏ trống ngày xem tiếp.","e":{"khien":1,"tamma":-2}},{"l":"Tra dấu cũ, không mở quẻ mới","t":"Ngươi nhờ họ đọc bản chép cũ, chỉ được chỗ còn mơ hồ trên giấy. Chủ kho tự quyết giờ mở, còn ngươi phải quay mặt vào vách khi đèn được thắp.","e":{"khien":1,"st":2}}]},{"ma":"S07","ten":"Đổi mệnh cho người khác","text":["Một người cha đưa ngươi chiếc áo của đứa trẻ và xin nhận phần yểu mệnh thay con. Trong quẻ có dáng người đứng bên giường, nhưng đường chỉ chưa nối tới đâu.","Người cha vẫn muốn làm khi nghe rằng cả hai đều có thể hao thọ. Tóc bên thái dương ngươi đã bạc đi chỉ sau khi nhìn thế quẻ."],"c":[{"l":"Chỉ làm khi cha tự nhận cái giá","t":"Ngươi hỏi lại trước mặt người nhà rồi mới đổi dấu trên quẻ. Đứa trẻ qua được cơn nguy, còn người cha hụt hơi ngay khi cúi xuống nhặt chiếc áo.","e":{"deed":"nghich_thien","tho":1,"res":2}},{"l":"Khép quẻ và tìm cách chữa","t":"Ngươi tháo thẻ khỏi dây, giúp người cha đưa đứa trẻ tới nơi chữa. Bên đường, cả hai dừng nghỉ vì tay ngươi còn run và người cha chưa hết ho.","e":{"hd":[3,0],"hp":"-5%"}}]},{"ma":"S08","ten":"Đoán sai","text":["Ngươi đã bảo đoàn xe tránh con đường ven ruộng vì thấy nước dâng. Sáng sau, con đường ấy vẫn khô, còn xe đã đi theo lối bị lở.","Người chở hàng mang tới dải vải buộc từ bánh gãy. Ngươi nhìn thấy tay mình run vì phí thọ hôm qua và biết lời đoán vẫn đã sai."],"c":[{"l":"Nhận sai và góp công dỡ xe","t":"Ngươi mang ván tới chỗ lở rồi cùng người chở nhấc hàng xuống. Họ yêu cầu ngươi sửa tờ báo quẻ ở trạm trước khi lấy lại tiền đã trả.","e":{"st":-2,"danh":3,"tamma":-2}},{"l":"Công bố bản quẻ cho họ đối","t":"Ngươi treo bản chép bên lời báo của người giữ đường, gạch rõ chỗ mình đã suy sai. Đoàn xe tự đi tìm lối, còn người tới xem quẻ sau đọc tờ ấy trước khi ngồi.","e":{"danh":4,"res":-1}}]},{"ma":"S09","ten":"Thiên cơ các truy sát kẻ lộ thiên cơ","text":["Người của {FA03} chặn ngươi trước cửa trạm và đòi bản quẻ đã lọt ra ngoài. Trong tay họ là tờ sao chỉ còn phần kết, mất hết dòng ngươi ghi còn nghi.","Ngươi đã hao thọ khi mở quẻ, và chân trở nặng lúc muốn đi nhanh. Người đưa giấy còn trong quán, chưa biết ngoài cửa có người đợi."],"c":[{"l":"Giao cả bản đối chứng","t":"Ngươi trải bản đủ ra bàn, chỉ chỗ họ đã bỏ mất dòng còn nghi. Người truy giữ ngươi lại để hỏi, còn người đưa giấy được rời trạm qua cửa trước.","e":{"hp":"-10%","res":-1}},{"l":"Đưa người chuyển giấy ra cửa sau","t":"Ngươi để lại bản quẻ trên ghế và ra hiệu cho người chuyển giấy đi cùng. Họ thoát được trước, còn ngươi phải dừng ngoài bờ dốc để lấy lại hơi.","e":{"deed":"cuu_nguoi","mp":"-15%"}}]},{"ma":"S10","ten":"Đứa trẻ có mệnh đế vương","text":["Đứa trẻ nghịch góc bản đồ, dùng hạt đậu chặn ngay chỗ vẽ cửa thành. Trong quẻ, ngươi thấy bóng nó ngồi trên ghế cao, còn phía sau trống rỗng.","Hơi lạnh đã lan tới ngực ngươi, vậy mà người đưa trẻ tới vẫn muốn nghe ngươi nói chắc. Ngoài cửa, đứa trẻ hỏi có được mang hạt đậu về gieo không."],"c":[{"l":"Giữ lời quẻ trong sổ riêng","t":"Ngươi nói với người nhà rằng hình chỉ là một ngả, rồi cất bản. Đứa trẻ lấy hạt đậu về, và người nhà chưa đặt người canh ngoài cửa.","e":{"res":1,"tamma":-2}},{"l":"Cho gia đình xem với lời dè dặt","t":"Ngươi để họ đọc cả hình lẫn phần chưa rõ. Họ thuê thầy đến nhà, còn đứa trẻ phải để hạt đậu lại vì từ mai không được chạy ra bờ ruộng một mình.","e":{"st":3,"tho":0.5}}]},{"ma":"S11","ten":"Xem tận thế","text":["Trong quẻ, ngươi thấy dãy bếp tắt trước khi trời tối. Ngoài khung cửa, một ngọn lửa vẫn cháy đều dưới đáy nồi, không khớp với bóng vừa hiện.","Phải chống cả tay xuống bàn ngươi mới đứng dậy được. Người nghe hỏi nên báo dân rời đi hay chỉ giữ đề phòng khi có dấu thật."],"c":[{"l":"Báo những dấu có thể kiểm","t":"Ngươi chỉ cho họ đối ngày bếp tắt với gió và nước ở trạm. Người giữ trạm chuẩn bị chỗ trú, còn ngươi dừng xem để cơn đau không tăng thêm.","e":{"danh":5,"hd":[3,0]}},{"l":"Đặt quẻ khác cạnh quẻ cũ","t":"Ngươi mở thêm quẻ và thấy có bếp còn đỏ dưới bóng tối. Thọ nguyên đã hao mà hai hình vẫn khác, nên ngươi chỉ gửi giấy ghi những chỗ chúng cùng hiện.","e":{"tho":1,"res":3,"xp":4}}]},{"ma":"S12","ten":"Quẻ cuối","text":["Ngươi đặt thẻ cuối lên tấm vải đã sờn ở chỗ từng cầm. Trong quẻ thấp thoáng lối rẽ giữa sương, còn chân ngươi lạnh tới mức chẳng còn cảm được mép chiếu.","Ngoài cửa có người vẫn đợi lời dặn của ngươi. Phần thọ còn lại có thể đem gieo, hoặc để ngươi gọi họ vào và nói hết chuyện cần nói."],"c":[{"l":"Gieo quẻ cho mình","t":"Ngươi lật thẻ và thấy bóng người tản về những ngả khác nhau. Cảnh vẫn mờ, nhưng tới lúc họ vào, bàn tay ngươi đã không đủ sức thu thẻ.","e":{"tho":1,"tv":6}},{"l":"Khép vải và gọi người vào","t":"Ngươi bọc thẻ lại, nhờ người kia tới sát cửa giường. Họ được nghe ngươi dặn chỗ cất bản quẻ dở và ai cần trả phần lễ còn nợ.","e":{"tamma":-5,"hd":[1,0]}}]}],"ket":{"K01":{"ten":"Thiên cơ tử","canh":["Khách đến {LOC05} mang theo lời đồn rằng ngươi thấy được mọi ngả. Ngươi đặt trước mặt họ bản chép cả những lần đoán sai, rồi trải vải cho lượt xem tiếp.","Mỗi lần thẻ đổ, bàn tay ngươi lại lạnh thêm. Người học ngồi bên tự ghi chỗ quẻ bỏ trống trước khi chép lời ngươi."]},"K02":{"ten":"Mù vì thiên khiển","canh":["Sau cơn đau, ngươi đưa tay về phía đèn mà chẳng thấy bóng mình trên bàn. Người học kéo đĩa thẻ tới sát ngón tay để ngươi nhận ra mép vải.","Từ hôm đó, khách đọc câu hỏi thành tiếng. Ngươi tập nghe hết lời rồi hỏi lại họ muốn biết điều gì, trước khi quyết định có mở quẻ."]},"K03":{"ten":"Chết vì lộ thiên cơ","canh":["Người truy tìm ngươi tới trạm khi bản lời quẻ đã được chuyền sang bờ. Sáng hôm sau, chiếc chiếu ngươi nằm vẫn còn hơi ẩm, nhưng người giữ trạm gọi mãi không thấy ngươi đáp.","Họ giữ lại tờ ghi các dấu chưa rõ cùng bản sao đã phát ra. Người đến tìm về sau đọc được vì sao một câu còn nghi lại thành lời quyết."]},"K04":{"ten":"Tỉnh mộng","canh":["Ngươi đặt bản quẻ cuối cạnh các bản đã chép và nhìn thấy cùng một lối rẽ ở phần giấy còn trống. Dưới nền đá vang tiếng nước, chẳng lời nào xác nhận bên kia có gì.","Ngươi đứng lên khi tay bắt đầu lạnh và bước về phía lối rẽ. Trước khi đi, ngươi để lại các thẻ chưa lật cho người sau tự dò."]}}},"TU22":{"ten":"Thương tu","sk":[{"ma":"S01","ten":"Chuyến hàng linh vật đầu","text":["Ở {LOC03}, ngươi đặt hàng lên cân trước giờ xe đi. Người chở chỉ vào chiếc hòm lỏng đai, bảo qua dốc xóc thì dấu niêm sẽ rách.","Trong khế có ghi rõ ngày giao. Quầy thợ bên cạnh còn mở, nhưng để họ sửa xong thì xe phải chờ tới lúc chợ vãn."],"c":[{"l":"Đóng lại đai rồi gửi hàng","t":"Ngươi giữ xe lại và trả thêm công đóng đai. Hòm tới nơi nguyên niêm, còn người mua ghi ngày nhận muộn ngay cạnh dấu của ngươi.","e":{"st":-1,"danh":2,"xp":2}},{"l":"Chia hàng sang hòm của xe","t":"Ngươi xin người chở nhường chỗ trong hòm của họ rồi lập lại giấy giao. Xe đi đúng hẹn, nhưng tiền chuyến phải chia cho cả người cho mượn chỗ.","e":{"st":1,"res":1}}]},{"ma":"S02","ten":"Bị cướp ở biên khu","text":["Xe trước đổ nghiêng ở trạm giáp biên, dây buộc hàng đã bị cắt. Người dẫn đường thở gấp và bảo nhóm cướp còn đứng ngay lối xe quay đầu.","Trong bụi có phu xe ôm chân, còn chiếc hòm ngươi đã vay tiền để mua nằm giữa đường. Sau lưng ngươi, người kéo xe hỏi phải gỡ ngựa đi lối nào."],"c":[{"l":"Bỏ xe để đưa phu bị thương đi","t":"Ngươi tháo ngựa, đỡ phu xe lên yên rồi men theo rãnh về trạm. Khi quay lại có người theo, đám cướp đã kéo hòm khỏi đường.","e":{"deed":"cuu_nguoi","st":-3}},{"l":"Đổi hòm lấy lối đi","t":"Ngươi để hòm giữa đường và gọi cho họ lui đủ xa. Người bị thương lên được xe, còn khách mua phải nhận tin rằng hàng đã bị đem đi.","e":{"st":-2,"danh":-2}}]},{"ma":"S03","ten":"Đấu giá gian lận","text":["Người xướng giá vừa khép sổ thì ngươi thấy phiếu cao nhất vẫn còn giắt sau cổ tay họ. Linh vật đã được chuyển sang khay của người trả thấp hơn.","Chủ hàng đứng ngoài hàng ghế, chờ lĩnh tiền để trả công. Ngươi có trong tay cuống phiếu còn hằn đúng dấu của lượt bị giấu."],"c":[{"l":"Đòi đọc lại phiếu trước sàn","t":"Ngươi đặt cuống phiếu lên khay và mời chủ hàng tới đối. Buổi bán phải mở lại, còn ghế của người xướng giá được dời khỏi bục.","e":{"hd":[3,0],"danh":4}},{"l":"Rút hàng của mình khỏi buổi bán","t":"Ngươi chỉ cho chủ hàng chỗ giữ cuống rồi rút lô của mình về. Chủ sàn vẫn chốt giá cũ, còn ngươi phải tự tìm khách cho chuyến tiếp theo.","e":{"st":-1,"res":1}}]},{"ma":"S04","ten":"Con nợ là tông môn","text":["Tờ khế đặt trên bàn có dấu sơn môn, nhưng người đón ngươi chỉ mang ra bao linh thạch nhẹ hơn khoản đến hạn. Dưới sân, đệ tử đã xếp hàng nhận phần dùng qua mùa.","Người giữ kho xin dời phần nợ tới vụ sau. Họ đặt trước mặt ngươi chìa cửa kho hàng, hỏi có muốn giữ chìa để làm tin không."],"c":[{"l":"Gia hạn và giữ bản kê","t":"Ngươi nhận phần đang có, chép ngày trả phần còn lại trước mặt họ. Đệ tử vẫn lĩnh được phần trong kho, còn ngươi phải lùi chuyến mua tiếp.","e":{"st":1,"danh":3,"hd":[1,0]}},{"l":"Nhận hàng thay khoản đến hạn","t":"Ngươi kiểm kho rồi chọn lô có thể bán lại, ghi giá ngay trên khế. Họ cho xe ngươi rời cổng, nhưng đơn đặt hàng mới được giao cho người khác.","e":{"st":3,"res":-1}}]},{"ma":"S05","ten":"Đầu cơ linh thảo trước thú triều","text":["Trước ngày thú triều tràn tới, các trạm bắt đầu hỏi mua linh thảo. Trong kho ngươi có bao còn tươi, ngoài sân có người đã trả trước chờ nhận.","Một lái hàng xin mua cả kho để bán khi đường ách lại. Người từ trạm chữa thú đem theo giấy hẹn cũ và cái giỏ chưa có gì."],"c":[{"l":"Giao linh thảo theo giấy hẹn","t":"Ngươi mở kho và cấp đúng phần đã hẹn cho từng trạm. Lái hàng bỏ giá cao đi, còn phu xe có đường giao hàng trước khi cổng đóng.","e":{"danh":5,"hd":[3,0],"st":1}},{"l":"Giữ kho chờ giá lên","t":"Ngươi khóa cửa và đợi tin đường bị chặn. Hôm sau người mua trả giá cao, nhưng nhà ở sát trạm chỉ đủ bạc đem về phần lá vụn.","e":{"st":5,"hd":[0,3],"danh":-4}}]},{"ma":"S06","ten":"Thương minh chèn ép","text":["Tới {LOC03}, ngươi thấy tên mình bị gạch trên bảng chia lượt xe. Người giữ bảng bảo thành viên đã đồng ý dành chỗ cho hàng của hội trước.","Chủ các xe nhỏ đứng ngoài cửa nghe cùng câu ấy. Có người muốn ký vào hội, có người mang theo bản đồ đường vòng qua chợ nước."],"c":[{"l":"Ký theo lệ của thương minh","t":"Ngươi nhận suất xe và đồng ý trả phần phí theo bảng mới. Khi tới phiên ngươi, các xe nhỏ vẫn phải đứng ngoài với hàng đã lên men.","e":{"st":2,"hd":[0,1]}},{"l":"Gom xe nhỏ đi tuyến khác","t":"Ngươi chia tiền thuê người dẫn đường với các chủ xe chờ ngoài cửa. Chuyến mất thêm ngày đường, nhưng mỗi nhà giữ được phiếu giao đứng tên mình.","e":{"danh":5,"res":1,"st":-1}}]},{"ma":"S07","ten":"Buôn hàng cấm cho ma tông","text":["Một người mua đặt khế ở mép bàn và dùng tay che dòng ghi nơi nhận. Món hàng bị cấm qua chốt, còn tiền trước đã nằm trong hòm ngươi.","Người theo xe chỉ mới được dặn chở hàng khô. Họ hỏi có nên lấy thêm bạt vì đêm nay phải dừng gần chốt hay không."],"c":[{"l":"Hủy chuyến, trả tiền cọc","t":"Ngươi mở hòm trả đủ tiền rồi nói với phu xe vì sao phải dỡ hàng. Khách mang khế bỏ đi, còn tiền công chuẩn bị do ngươi tự trả.","e":{"st":-2,"hd":[3,0]}},{"l":"Giữ chuyến và nói rõ món hàng","t":"Ngươi mở khế cho phu xe đọc, trả công cho người muốn rút rồi đưa phần còn lại đi. Khi hàng tới, người mua nhận hết và dặn chuyến sau tự lo người.","e":{"st":6,"hd":[0,3],"tamma":3}}]},{"ma":"S08","ten":"Linh thạch giả","text":["Viên linh thạch kêu đục khi chạm mặt cân. Ngươi thấy vết phủ đọng trong rãnh, đúng chỗ người trả tiền vừa miết ngón tay.","Người nhận công đã tới quầy, có người chờ tiền để kịp xe về. Còn trong hòm chỉ có ít linh thạch đã đối được dấu."],"c":[{"l":"Tách đá giả và giữ phiếu","t":"Ngươi để riêng số đá nghi giả rồi trả công bằng phần đã xác nhận. Người chưa đến lượt nhận phiếu hẹn để lần sau khỏi phải kể lại từ đầu.","e":{"st":-1,"danh":2}},{"l":"Bù công rồi đòi bên giao giải trình","t":"Ngươi lấy phần vốn dành mua hàng để trả công đúng lượt. Sau đó ngươi mang viên giả và biên nhận tới quầy đã giao, buộc họ mở sổ đối.","e":{"st":-2,"danh":4,"xp":3}}]},{"ma":"S09","ten":"Cứu một thương đội","text":["Thương đội mắc ở đoạn suối, bánh xe ngập tới trục. Họ đã tháo ngựa ra, nhưng người trông hàng không chịu bỏ hòm mà lên bờ.","Xe của ngươi còn dây kéo. Dùng dây để cứu xe sẽ lỡ buổi giao ở chợ, còn đưa người đi ngay thì kho hàng có thể bị nước cuốn."],"c":[{"l":"Kéo người lên trước","t":"Ngươi đưa dây cho người còn dưới nước, giữ chặt tới khi họ lên bờ. Hòm trôi mất, nhưng người trông hàng còn giữ được phiếu để báo chủ.","e":{"deed":"cuu_nguoi"}},{"l":"Kéo cả xe qua bãi cạn","t":"Ngươi gọi người đã lên bờ cùng ghì dây và xoay đầu xe. Hàng được cứu, còn người mua của ngươi rời chợ trước khi chuyến tới.","e":{"st":2,"res":1,"hp":"-8%"}}]},{"ma":"S10","ten":"Phường thị riêng","text":["Ngươi trải khế thuê đất cạnh phác đồ quầy ở {LOC03}. Người buôn nhỏ hỏi tiền kê sạp tính theo ngày hay theo cả mùa.","Người góp vốn chỉ chỗ tốt dưới mái và xin dành nó cho hàng nhà mình. Chỗ sát rãnh nước còn đủ rộng để mở thêm lối cho khách."],"c":[{"l":"Mở sạp theo phiên chung","t":"Ngươi ghi lượt sạp để mỗi nhà tự xem được ngày của mình. Người góp vốn lấy phần lời muộn hơn, nhưng lối sát rãnh được để trống cho khách.","e":{"danh":6,"hd":[1,0],"res":1}},{"l":"Cho người góp vốn chọn quầy trước","t":"Ngươi nhường quầy dưới mái để đổi lấy tiền dựng sạp sớm. Các nhà buôn nhỏ chuyển ra ngoài, tự kê ván qua rãnh cho khách tới.","e":{"st":5,"danh":-3}}]},{"ma":"S11","ten":"Tài thần giáng (tin đồn)","text":["Một người đi chợ đặt tiền lên quầy và bảo hàng qua tay ngươi bán sẽ gặp vận. Ngoài cửa, có người đã cầm món đồ đem cầm cố để lấy vốn theo chuyến.","Ngươi vừa nhận tin chuyến ấy có thể trễ vì cửa trạm hỏng. Người cầm món đồ vẫn đứng đợi ngươi ra giá cho họ góp phần."],"c":[{"l":"Nói rõ rủi ro trước khi nhận","t":"Ngươi cho họ đọc giấy trạm rồi để từng người quyết định. Nhà cần tiền gấp đem món cầm về, còn số vốn nhận được chỉ đủ cho chuyến ngắn.","e":{"danh":4,"st":1}},{"l":"Nhận phần góp theo giá đang chào","t":"Ngươi nhận vốn khi tin tốt còn lan ngoài chợ. Xe tới muộn, và lúc trả lời người góp, ngươi phải mở sổ bên cạnh những món đồ họ đã cầm.","e":{"st":5,"res":2,"tamma":3}}]},{"ma":"S12","ten":"Phá sản","text":["Người giữ quầy gỡ tấm biển xuống, để lộ vệt tường sạch phía sau. Trong hòm còn tiền lẻ và phiếu của các phu xe chưa lĩnh công.","Chủ nợ chờ ngoài cửa, còn người làm đã đến lấy đồ nghề. Ngươi phải nói họ được giữ giấy gì trước khi bàn giao chìa."],"c":[{"l":"Chia phần còn lại trước mặt các bên","t":"Ngươi đọc sổ và ghi món nợ còn thiếu trên từng phiếu. Chủ nợ nhận chìa kho, còn người làm giữ giấy có chữ của người đứng tên trả.","e":{"st":"-60%","deed":"giu_loi"}},{"l":"Bán hết hàng để ưu tiên trả công","t":"Ngươi bán lô cuối cho hàng bên cạnh rồi trả công đến hạn. Chủ nợ nhận quầy trống, giữ tờ khế chưa gạch và chờ ngươi ở phiên sau.","e":{"st":"-40%","danh":-3}}]}],"ket":{"K01":{"ten":"Tài thần","canh":["Ở {LOC03}, người giữ cân phải đổi sang sân rộng vì chuyến hàng chen kín cửa. Các lái buôn dùng dấu của ngươi để nhận hàng ở quầy mà chẳng cần ngươi có mặt.","Ngươi đi vòng qua mái sau và ghé chỗ người ghi phí. Trước mặt họ là sổ lời, bên dưới còn những biên nhận phải đối khi xe về."]},"K02":{"ten":"Phá sản, bị chủ nợ giết","canh":["Ngươi trả chiếc chìa cuối cùng, nhưng chủ nợ vẫn chặn đường ở ngõ hẹp. Sáng hôm sau, người làm tìm thấy ngươi bên tấm biển quầy đã tháo.","Họ đem phiếu tiền công ra bàn để tìm tên người có thể trả. Tờ kê nợ còn nguyên dấu, nhưng ghế đầu quầy đã trống."]},"K03":{"ten":"Quy ẩn với kho báu (chôn cho kiếp sau)","canh":["Ngươi thôi đứng tên chuyến và chở hòm cuối về chỗ đất khô. Trước khi lấp, ngươi giắt vào nắp mẩu giấy vẽ lối tính từ bậc cửa.","Sau vụ mưa, cỏ che khuất vết đào, còn mẩu giấy chép lại nằm trong sổ luân hồi. Người qua đường chỉ thấy bậc cửa thấp và chỗ vừa đủ kê chân."]},"K04":{"ten":"Thương minh truyền đời","canh":["Ngươi trao sổ giao nhận cho người sẽ trông phiên sau. Họ đọc lại cả giá và khoản phu xe được lĩnh, rồi mới gọi chuyến đầu.","Về sau, chữ ký trên khế đổi tay nhiều lượt. Các nhà vẫn giữ bản của mình để còn đối nếu hòm giao tới bị hỏng."]}}},"TU23":{"ten":"Lôi pháp sư","sk":[{"ma":"S01","ten":"Phù ướt trên nền đài","text":["Ở {LOC15}, gió hất tờ phù vào ống tay áo ngươi. Nét mực sáng lên ngay chỗ nước mưa thấm qua.","Người dạy đè hòn cuội lên tờ giấy. Dưới dốc, người nhặt củi còn men theo đường trống để về."],"c":[{"l":"Chờ đường vắng","t":"Ngươi đợi người nhặt củi đi khuất rồi mới đặt ấn xuống. Mực đã nhòe, nên ngươi phải vẽ lại tờ phù trước khi thử.","e":{"res":1,"xp":2,"hd":[1,0]}},{"l":"Dời buổi thử sang nền đá trống","t":"Ngươi mang phù sang mặt đá khuất đường đi. Tiếng lôi đến rõ, nhưng gió cuốn tờ phù xuống khe và ngươi phải quay lại tìm.","e":{"xp":3,"tv":2,"res":-1}}]},{"ma":"S02","ten":"Tiếng cào dưới bếp","text":["Ở {LOC01}, chủ nhà đưa ngươi cái bát mẻ. Sáng nào họ cũng thấy nó úp cạnh cửa, dù tối qua đã cất kỹ.","Khi ngươi chạm vào bát, âm khí kéo qua đầu ngón tay. Dưới gầm bếp còn góc áo trẻ con mà người chủ muốn lấy ra."],"c":[{"l":"Đưa người ra sân rồi trừ tà","t":"Ngươi chờ họ lấy áo, đưa cả nhà ra sân rồi mới đặt lôi ấn cạnh bếp. Tiếng cào dứt, nhưng người chủ phải nhờ ngươi kê lại viên gạch vừa bật khỏi nền.","e":{"deed":"cuu_nguoi","res":-1,"danh":2}},{"l":"Dẫn tà vật ra khỏi bếp","t":"Ngươi đặt bát ngoài sân, đợi bóng theo tới mới dùng lôi. Bếp còn nguyên, nhưng chiếc bát vỡ và người chủ nhặt lấy mảnh còn dấu tay đứa trẻ.","e":{"res":1,"xp":3,"hp":"-8%"}}]},{"ma":"S03","ten":"Hòm thi giữa trạm","text":["Một Thi tu dừng xe trước trạm, dây giữ hòm đã chùng. Ngón tay cứng từ trong hòm cào vào mép gỗ mỗi khi ngựa bước.","Người trực trạm xin ngươi đánh ngay vì khách đứng quá gần. Người chở hòm bảo gia quyến đang tới nhận áo liệm."],"c":[{"l":"Cho khách lùi rồi đánh thi luyện","t":"Ngươi đợi khách dạt khỏi xe rồi đánh lúc xác luyện vừa đẩy nắp. Hòm cháy sém, và người chở phải cắt riêng phần áo còn lành cho gia quyến.","e":{"res":2,"xp":3,"hp":"-10%"}},{"l":"Buộc Thi tu thu hiệu lệnh","t":"Ngươi giữ lôi ấn trong tay và yêu cầu người chở dừng xác để trả áo. Họ làm theo, còn ngươi đi cùng xe tới bãi để chắc chiếc hòm được khép.","e":{"hd":[2,0],"danh":3}}]},{"ma":"S04","ten":"Đá ẩm dưới đồng mộ","text":["Ở {LOC14}, âm khí đọng dày trong rãnh đất. Ngươi thử lôi ấn, vệt sáng vừa chạm đá đã tắt.","Người giữ mộ giơ đèn chỉ lối cao còn khô. Dưới chân bia, bóng xám đứng chắn đường gia quyến xuống đặt cơm."],"c":[{"l":"Dẫn bóng lên lối cao","t":"Ngươi đợi bóng men theo mép rãnh rồi dẫn nó khỏi vùng âm khí. Lôi ấn đánh tan được bóng, nhưng gia quyến phải dời mâm cơm muộn hơn giờ hẹn.","e":{"res":2,"xp":3,"mp":"-15%"}},{"l":"Giữ lối cho gia quyến rút","t":"Ngươi dùng luồng lôi yếu để giữ khoảng cách cho người đứng dưới bia quay lên. Bóng xám còn đó, nên ngươi ở lại canh tới khi mặt rãnh bắt đầu khô.","e":{"deed":"cuu_nguoi","hd":[1,0]}}]},{"ma":"S05","ten":"Bóng ôm bao thóc","text":["Người coi kho bảo ngươi trừ bóng đêm nào cũng ôm bao chạy qua sân. Ngươi thấy nó chỉ đi đúng quãng đường tới chỗ từng phát thóc.","Một bà lão đưa tờ phiếu còn dấu ngón tay của con mình. Bà xin đặt phiếu xuống trước khi ngươi dùng lôi."],"c":[{"l":"Để bà trả phiếu trước","t":"Ngươi chừa lối cho bà tới bên bao. Bóng buông tay khi bà gọi đúng tên, và ngươi dùng lôi đánh tan phần âm khí còn bám trên vải.","e":{"hd":[2,0],"tamma":-3}},{"l":"Dùng ấn đuổi bóng khỏi kho","t":"Ngươi dẫn mọi người ra ngoài rồi giáng lôi xuống sân. Bóng tan, nhưng tờ phiếu bà đặt sát bao chỉ còn mép cháy đen.","e":{"res":2,"xp":3,"tamma":3}}]},{"ma":"S06","ten":"Ánh trắng ở đầu cầu","text":["Sấm đánh gãy cọc, để cầu treo xệ xuống sát nước. Dưới mái trạm có người ướt sũng vẫn nhìn sang bờ kia, chỗ người nhà đang mắc lại.","Luồng lôi trong tay ngươi bắt nhịp với vệt sáng trên sườn núi. Chỗ có thể thử sức lại cách xa đầu cầu đang cần người giữ."],"c":[{"l":"Giữ đầu cầu cho người qua","t":"Ngươi chống vai vào cọc và giữ dây tới khi người cuối sang bờ. Luồng lôi trong tay tan dần, còn người nhà chia nhau hong áo dưới mái trạm.","e":{"deed":"cuu_nguoi","mp":"-20%"}},{"l":"Rời cầu để thử dẫn lôi","t":"Ngươi nhờ người coi trạm giữ khách lại rồi lên chỗ đá trống đón sét. Ngươi dẫn được luồng lôi xuống đá, nhưng nước dâng buộc cả trạm chờ đến sáng mới sang.","e":{"tv":5,"xp":4,"danh":-3}}]},{"ma":"S07","ten":"Dấu than trên tay nắm","text":["Tới nhà bị ám, ngươi thấy than vương trên mặt trong tay nắm. Chủ nhà cho đó là dấu tà vật, song ngươi nghe tiếng ho sau chỗ vách mới ghép.","Người làng đã tụ ngoài cửa, muốn ngươi kết việc trước đêm. Trong tay ngươi có lá phù còn nguyên nét."],"c":[{"l":"Mở vách và hỏi người đang trốn","t":"Ngươi gỡ tấm ván, để người nhóm than tự kể vì sao họ nấp. Đám đông giải tán chậm, còn chủ nhà phải xin ngươi xét lại tiếng gõ ở gian bếp.","e":{"hd":[2,0],"danh":3,"tamma":-2}},{"l":"Giáng lôi vào tay nắm","t":"Ngươi đánh vào tay nắm và tấm ván bật ra. Tiếng ho hóa thành tiếng gọi cứu, buộc ngươi bỏ phù xuống để đưa người bị thương ra.","e":{"res":3,"xp":4,"tamma":5,"hd":[0,2]}}]},{"ma":"S08","ten":"Trước tiếng sấm cuối","text":["Trên nền {LOC15}, khí trời nặng tới mức ngọn đèn chao mà không tắt. Lôi ấn trong tay ngươi rung theo tiếng sấm từ sườn núi.","Người học đứng ở bậc dưới, cầm chiếc áo khô ngươi gửi. Họ hỏi có nên đợi ở đó hay xuống dốc trước khi ấn mở."],"c":[{"l":"Cho người học lùi rồi đón sét","t":"Ngươi đợi họ xuống hết bậc mới xoay ấn theo luồng sáng. Lôi đi qua nền đá. Ngươi vẫn đứng được khi người học mang áo khô trở lại.","e":{"tv":6,"xp":5,"hp":"-15%"}},{"l":"Khép ấn và xuống đài","t":"Ngươi dập nét ấn trước khi sấm tới gần rồi theo người học xuống. Sét đánh trúng chỗ đứng cũ, buổi thử phải hẹn lại khi đường dẫn được sửa.","e":{"hd":[1,0],"tamma":-3}}]}],"ket":{"K01":{"ten":"Người giữ ngọn đèn qua bão","canh":["Người làng gọi ngươi sang khi tiếng cào trở lại dưới mái. Ngươi để họ tự chọn đồ muốn mang ra rồi mới dựng lôi ấn ở sân.","Về sau, hễ mưa lớn, họ chừa lối khô cho người đến giúp và thắp đèn chỉ chỗ bậc trơn. Ngươi tới chỉ việc đặt tay lên then, chẳng cần ai giục mở."]},"K02":{"ten":"Vết sét trên vách nhà","canh":["Ngươi mở ấn khi người sau vách còn chưa lên tiếng. Lôi dội qua gỗ ẩm, để lại vết cháy ngay ngang tay người từng níu cửa.","Từ đó, ngươi đứng ngoài mỗi khi có nhà mời vào trừ tà. Chiếc áo người học đem trả còn gấp nếp cũ, nhưng bàn tay ngươi chẳng giữ được ấn."]}}},"TU24":{"ten":"Huyễn thuật sư","sk":[{"ma":"S01","ten":"Bóng rơi khỏi bát nước","text":["Ở {LOC04}, ngươi nhìn bóng ngọn đèn trong bát nước. Khi gió tắt ở cửa, cái bóng vẫn lay như còn ai đi ngang.","Người dạy đặt chiếc thìa bên bát và mời ngươi thử giữ hình cho tới khi có khách bước vào. Trên thềm, người đi đường đang gỡ bùn khỏi dép."],"c":[{"l":"Báo trước rồi cho khách xem","t":"Ngươi nói trước đây là cảnh dựng và mời khách quấy nước. Hình tắt ngay đầu thìa, nhưng họ chỉ cho ngươi biết nó đã lệch từ lúc nào.","e":{"hd":[1,0],"danh":2}},{"l":"Giữ hình tới khi khách tự nhận ra","t":"Ngươi giữ bóng qua lúc khách vào, khiến họ đặt đèn thật xuống chỗ tưởng có chỗ tựa. Đèn nghiêng đổ, và ngươi mất buổi học để lau dầu khỏi chiếu.","e":{"res":2,"xp":3,"danh":-2}}]},{"ma":"S02","ten":"Dựng mái hiên cho lễ tế","text":["Người trông lễ ở {LOC02} thuê ngươi dựng cảnh mái nhà cũ trên sân. Họ đem tới tấm rèm bạc màu, xin giữ đúng vết rách ở góc dưới.","Người góp tiền lại muốn ngươi làm mái mới hẳn để khách khỏi thấy nhà từng tiêu điều. Gia quyến đã xếp ghế, chờ nghe người trông lễ báo bắt đầu."],"c":[{"l":"Dựng lại mái nhà đúng dấu cũ","t":"Ngươi giữ vết rách và để người nhà tự chỉ nơi họ từng ngồi. Chủ lễ trả công theo hẹn, còn người góp tiền đứng ngoài hàng ghế tới lúc cảnh tan.","e":{"hd":[1,0],"st":-2,"tamma":-2}},{"l":"Dựng mái mới theo lời người góp","t":"Ngươi làm mái sáng màu và giấu vết rách sau bóng rèm. Người góp tiền đứng ra nhận lời khen, còn gia quyến phải mang rèm thật lên sân để chỉ chỗ cũ.","e":{"st":4,"res":1,"danh":-2}}]},{"ma":"S03","ten":"Mẻ bạc dưới lòng cân","text":["Ngươi thấy gã lái buôn đẩy quả cân về phía đĩa đã có chì. Người bán đang cúi nhặt hàng, chẳng nhìn ra vì sao phần bạc của mình cứ vơi.","Gã lái buôn chỉ nhìn đĩa nặng và đã đưa tay về phía bạc trên quầy. Ngươi có thể dựng một bóng bạc để gã phải đặt lại cân."],"c":[{"l":"Nhử gã tự cân trước mặt người bán","t":"Ngươi để bóng bạc hiện lệch khỏi đĩa. Gã nhấc quả nặng ra xem, và người bán thấy rõ miếng chì trước khi cho cân lại.","e":{"danh":3,"hd":[1,0]}},{"l":"Dùng bóng bạc đổi lấy quả cân","t":"Ngươi để gã chụp vào bóng rồi cầm quả cân đi. Người bán giữ được mẻ hàng sau, song lượt bạc đã trả thiếu không quay lại với họ.","e":{"st":5,"res":1,"hd":[0,1]}}]},{"ma":"S04","ten":"Khung cửa bên giường","text":["Người sắp tắt thở ở trạm xin được nhìn qua khung cửa nhà. Người đi cùng đặt bát nước lên bàn, bảo bên ngoài cửa thật chỉ có tường kho.","Họ nhớ bậc cửa thường hứng nắng ở cạnh nào, nhưng chẳng còn nói đủ hơi. Ngươi có thể dựng cảnh từ điều vừa nghe hoặc để người nhà kể tiếp."],"c":[{"l":"Dựng bậc cửa trống","t":"Ngươi dựng vệt nắng sát ngạch và để cảnh đứng yên. Người bệnh thả lỏng tay, còn người nhà tự ngồi vào chỗ sáng để được nhìn thấy.","e":{"deed":"cuu_nguoi","tamma":-3}},{"l":"Dựng cảnh cùng lời người nhà","t":"Ngươi giữ nền cửa mờ và chờ từng lời kể mới thêm vào. Người bệnh chưa kịp thấy hết sân, nhưng nghe rõ tiếng người nhà nhắc chỗ họ từng đặt dép.","e":{"xp":4,"res":2,"tamma":2}}]},{"ma":"S05","ten":"Gương đẩy bóng ngược","text":["Ở sân tập, đối thủ nhìn thẳng qua bóng ngươi dựng và chạm tay vào mặt gương. Cảnh giả gập lại, đập ngược vào mắt khiến ngươi choáng tới mức phải vịn bàn.","Người coi sân đã đưa khăn tới. Đối thủ hỏi ngươi có muốn dừng hay thử tìm chỗ họ vừa nhìn ra."],"c":[{"l":"Dừng để đối lại từng dấu","t":"Ngươi ngồi xuống và nhờ họ chỉ nét đầu tiên bị lộ. Hóa ra bóng trong gương quay đầu chậm hơn thân người, và ngươi ghi lại lỗi sau khi hết choáng.","e":{"xp":4,"tv":2}},{"l":"Giữ buổi thử bằng cảnh đơn giản","t":"Ngươi đợi đứng vững rồi chỉ dựng bóng ngọn đèn trên vách. Đối thủ vẫn thấy vết lệch, nhưng lần này ngươi tự dập hình trước khi cảnh dội lại.","e":{"res":1,"mp":"-10%"}}]},{"ma":"S06","ten":"Người gác sau tấm phên","text":["Trong kho gần {LOC09}, người giữ hàng nhờ ngươi dựng bóng lính để kẻ tới khuân trộm bỏ đi. Qua phên, ngươi thấy một người còn trẻ đến nhặt chiếc bị đã để quên từ chiều.","Người giữ kho đã gọi khách quanh bến tới nhìn. Bóng trên vách đủ giống người có thật để họ tin kẻ vừa vào đã bị bắt quả tang."],"c":[{"l":"Dẹp bóng và cho người ấy tự nói","t":"Ngươi thu cảnh rồi mở phên. Người trẻ lấy bị ra cho mọi người xem, còn người giữ kho phải tự đi kiểm chỗ hàng thiếu.","e":{"hd":[1,0],"danh":2}},{"l":"Giữ bóng để kho trống qua đêm","t":"Ngươi để bóng đứng ở cửa và bảo người nhặt bị quay ra. Tới sáng, hàng còn nguyên, nhưng ngoài chợ đã có lời đồn rằng ngươi dùng hình giả để làm chứng.","e":{"st":3,"res":2,"tamma":3}}]},{"ma":"S07","ten":"Chợ lặp lại sau rèm","text":["Ngươi dẹp cảnh ở sân xong mà tiếng hàng rao vẫn vọng ra sau rèm. Cùng một tấm khăn rơi xuống mép bàn, lần nào cũng gấp đúng nếp.","Người coi sân gọi ngươi từ ngoài cửa và gõ lên mặt gỗ. Tiếng gõ có chỗ hụt, khác tiếng đều trong cảnh ngươi vừa dựng."],"c":[{"l":"Theo tiếng gõ ra khỏi sân","t":"Ngươi quay về nơi tiếng gõ hụt và lần được chốt cửa thật. Khi rèm buông, trong tay ngươi còn tấm khăn đã nhặt, ướt sũng chỗ tưởng khô.","e":{"tamma":-4,"xp":2}},{"l":"Ở lại lần tới chỗ cảnh lặp","t":"Ngươi nâng mép rèm, tìm thấy hình bắt đầu từ vệt đèn trên khay nước. Lúc dập đèn, ngươi lại không nhận ra người coi sân cho tới khi họ gọi đúng món đồ ngươi đã gửi.","e":{"res":3,"xp":5,"tamma":6}}]},{"ma":"S08","ten":"Phiên diễn không còn màn","text":["Trước giờ diễn, người trông sân lấy rèm đi che nhà dột. Khách vẫn tới, có người nghe đồn hôm nay sẽ được gặp lại người đã khuất.","Ngươi chỉ còn khoảng sân trống và những chiếc đèn thấp. Gần cửa, người đã trả công đợi ngươi nhận sẽ dựng đến đâu."],"c":[{"l":"Cho khách thấy cảnh thành hình","t":"Ngươi đặt đèn giữa sân rồi giải thích trước khi dựng bóng. Có người rời ghế, còn những người ở lại tự kể chuyện khi bóng đã tắt.","e":{"danh":4,"hd":[1,0]}},{"l":"Dựng cảnh kín dưới bóng đèn","t":"Ngươi tắt đèn sát cửa để hình hiện ra mà khách không trông thấy ngươi. Buổi diễn đông đến lúc hạ bóng, rồi có người cứ gọi theo hình đã tan và không chịu đứng dậy.","e":{"st":6,"res":2,"tamma":4}}]}],"ket":{"K01":{"ten":"Người mở rèm trước khách","canh":["Ngươi dùng đèn thấp soi bàn tay dựng cảnh để khách biết bóng từ đâu tới. Ai muốn dừng chỉ việc kéo tấm rèm về phía mình.","Người coi sân vẫn giữ những chiếc ghế phía ngoài cho người chỉ muốn nghe kể. Cuối buổi, ngươi dọn đèn trước, để người xem tự nói điều họ vừa thấy."]},"K02":{"ten":"Dấu tay trên cửa giả","canh":["Ngươi lần theo khung cửa đến mức lòng bàn tay rát. Bên cạnh có người gọi, nhưng tiếng ấy vừa dứt đã trở lại từ bức tường đối diện.","Sáng nào người coi sân cũng đặt nước ngoài rèm. Có hôm ngươi uống được, có hôm chỉ ngồi đợi mặt nước ngừng chiếu một bàn tay đang gõ cửa."]}}},"TU25":{"ten":"Thôn phệ tu","sk":[{"ma":"S01","ten":"Bát nước ở cửa cốc","text":["Ở {LOC07}, người truyền phép đặt bát nước trước mặt ngươi và bảo thử dẫn chút linh lực từ tay họ. Khi ngươi buông tay, mặt nước vẫn còn rung.","Người ấy kéo tay áo xuống rồi hỏi ngươi có muốn thử tiếp trên kẻ vừa chết ở ngoài sân không. Bên cổng có người đang chờ nhận thi thể."],"c":[{"l":"Dừng ở phần linh lực đã thử","t":"Ngươi trả bát và ra mở cổng cho người nhà. Ngón tay còn tê, song ngươi vẫn cầm được đầu chiếu giúp họ khiêng người đi.","e":{"hd":[1,0],"xp":1}},{"l":"Thử nuốt phần khí còn lại","t":"Ngươi đợi người giữ sân xác nhận đối thủ đã tắt thở rồi kéo phần khí còn vương vào mình. Tay hết tê, nhưng khi bưng nước cho gia quyến, ngươi nghe tiếng mình cười khẽ dù môi chưa động.","e":{"tv":5,"res":2,"tamma":4,"hd":[0,2]}}]},{"ma":"S02","ten":"Mùi sắt trong mỏ cũ","text":["Người coi mỏ thuê ngươi nuốt luồng tà khí thoát ra quanh cửa hầm. Chốt cửa rịn hơi lạnh, còn mùi sắt bám vào răng dù ngươi chưa bước qua.","Thợ đã đứng ngoài với đèn và giỏ cơm. Họ cần biết ngươi sẽ làm ngay hay đợi đất trên cửa thôi rơi."],"c":[{"l":"Nhận việc sau khi thợ rời dốc","t":"Ngươi chờ họ lui rồi hút luồng khí khỏi cửa. Đèn thôi chao, nhưng tối ấy ngươi nghe trong đầu tiếng gõ mà ngoài vách chẳng có ai.","e":{"res":3,"xp":3,"tamma":4}},{"l":"Dừng việc và giữ cửa hầm","t":"Ngươi trả phần đã ứng rồi bảo thợ sang lán chờ. Người coi mỏ phải tìm cách khác, còn ngươi giữ cửa tới khi chuyến cuối rời dốc.","e":{"st":-2,"hd":[1,0]}}]},{"ma":"S03","ten":"Tay áo dưới gốc trâm","text":["Đối thủ vừa ngã, ống tay mắc vào rễ trâm. Luồng khí còn quanh người ấy rút chậm đến mức ngươi cảm được nó qua lòng bàn chân.","Ngươi cúi xuống thì thấy sợi dây giữ một lá thư còn niêm. Người ở đầu dốc đang gọi xem có ai sống sót không."],"c":[{"l":"Nuốt khí rồi giao lá thư","t":"Ngươi kéo luồng khí về kinh mạch rồi trao thư cho người chạy tới. Họ nhận thư, còn ngươi phải đứng yên một lúc vì cơn nóng cứ chạy ngược lên cổ.","e":{"tv":4,"res":2,"tamma":3}},{"l":"Giữ nguyên thư và gọi người liệm","t":"Ngươi dằn tay xuống đất, đợi cho luồng khí tan. Người đầu dốc nhận ra dấu trên thư và nhờ ngươi chỉ đúng chỗ người ấy đã ngã.","e":{"deed":"an_tang","tamma":-3}}]},{"ma":"S04","ten":"Khí mượn giữa buổi tĩnh tọa","text":["Ngươi vừa ngồi yên thì luồng khí đã nuốt chạy ngược thế dẫn quen thuộc. Chiếc chén bên gối đổ, nước lạnh thấm vào chiếu.","Người tập cùng nghe động và đặt tay lên cửa, hỏi có nên vào đỡ. Ngươi biết lượng khí ấy chưa chịu theo hơi thở của mình."],"c":[{"l":"Rời chiếu trước lúc bước tiếp","t":"Ngươi gọi người ngoài vào và tháo thế ngồi khi họ đỡ vai. Cơn nghẹn lắng dần, nhưng buổi đột phá phải dời tới khi ngươi vận được hơi của mình.","e":{"tamma":-3,"hp":"-5%"}},{"l":"Cố dẫn khí qua chỗ nghẹn","t":"Ngươi ghì hơi qua ngực và giữ thế ngồi. Luồng khí dội ngược, bàn tay không còn đủ sức nâng chiếc chén mà người kia đưa tới.","e":{"tv":7,"xp":4,"hp":"-20%","tamma":5}}]},{"ma":"S05","ten":"Lời gọi sau bàn cơm","text":["Người bán cơm đặt bát trước mặt ngươi rồi quay đi hâm nước. Trong tiếng thìa chạm thành nồi, ngươi nghe rõ lời thúc mình đi tìm kẻ vừa gục ngoài đường.","Khi ngươi đứng dậy, người bán hỏi vì sao chưa đụng đũa. Mùi cơm còn nóng, còn tiếng trong đầu đã nhắc lại lời cũ."],"c":[{"l":"Ngồi lại cho tới khi tiếng lắng","t":"Ngươi nhờ người bán giữ ghế và ăn chậm tới khi phân biệt được tiếng bếp. Ngoài đường đã yên, nhưng lúc trả tiền ngươi vẫn phải dùng cả tay để cầm bát.","e":{"tamma":-4}},{"l":"Đi theo tiếng gọi","t":"Ngươi để bát nguyên rồi ra đầu đường. Người bị thương đã được đưa đi, còn ngươi lần theo dấu kéo tới tận trạm trước khi nhận ra mình đã bỏ cả tay nải ở quán.","e":{"res":2,"xp":3,"tamma":4}}]},{"ma":"S06","ten":"Người mang chiếc thắt lưng","text":["Trên đường dốc, một người chìa chiếc thắt lưng đã sờn và hỏi ngươi có gặp chủ của nó không. Ngươi nhận ra nút thắt của người vừa bị mình lấy mất phần khí.","Sau lưng họ là người trông bãi, cầm tờ giấy chờ ghi nơi tìm thấy thi thể. Ngươi có thể nói rõ việc đã làm hoặc chỉ cho họ đường xuống."],"c":[{"l":"Tự kể mình đã lấy gì","t":"Ngươi chỉ đúng chỗ rồi ở lại khi họ hỏi luồng khí đã đi đâu. Gia quyến giữ tờ ghi lời ngươi và yêu cầu ngươi rời bãi trước khi họ khâm liệm.","e":{"hd":[2,0],"danh":-3,"tamma":-4}},{"l":"Chỉ lối và giữ kín việc nuốt khí","t":"Ngươi vạch đường xuống bãi trên đất rồi bước đi. Đến trạm sau, họ đã nhờ người mang chiếc thắt lưng đi hỏi những ai gặp ngươi trước trận.","e":{"danh":2,"tamma":4}}]},{"ma":"S07","ten":"Đèn của người truy hỏi","text":["Người của chính đạo dựng đèn ngang lối và đọc tên những người đã ngã trong vùng. Họ mang giấy của gia quyến đi theo, chờ ngươi nhận việc nào mình đã làm.","Ngươi nghe tâm ma giục tiến lên, đúng lúc có người giữ đèn bước hụt trên đá. Phía sau dốc vẫn còn mái trạm có người đi đường trú."],"c":[{"l":"Đặt giấy xuống trước hàng đèn","t":"Ngươi trao bản ghi và lùi lại để người truy đối từng việc. Họ đưa ngươi ra khỏi dốc để hỏi tiếp, còn người trượt chân tự vịn được vào cọc.","e":{"danh":-4,"hd":[2,0],"tamma":-3}},{"l":"Lùi qua lối trạm bỏ trống","t":"Ngươi rời đường đèn và vòng khỏi chỗ khách đang trú. Người truy không bắt kịp, nhưng tới sáng lời gọi trong ngực ngươi vẫn chưa im.","e":{"res":1,"xp":3,"danh":-3}}]},{"ma":"S08","ten":"Cửa hang không nghe gió","text":["Luồng khí tụ dưới cửa hang làm ngọn đèn nghiêng hẳn vào lòng núi. Ngươi vừa đặt tay lên đá đã thấy trong miệng có vị bát nước bỏ lâu.","Người giữ đèn đợi ngươi kéo tiếp hay rời khỏi vạch. Đường ra vẫn mở, song cơn đói trong ngực đã át cả tiếng gió."],"c":[{"l":"Mở kinh mạch đón luồng khí","t":"Ngươi đứng lại để luồng khí tràn hết qua mình. Lúc bước ra, người giữ đèn gọi ngươi bằng tiếng từng nghe quen, và ngươi chỉ còn nhận ra hơi ấm của họ.","e":{"tv":8,"res":4,"tamma":8}},{"l":"Rút tay và để luồng khí tan","t":"Ngươi rời vạch rồi nhờ người giữ đèn đi trước. Đến khi nhìn thấy trời, ngươi vẫn nghe tiếng giục quay lại, nhưng đã gọi được họ bằng giọng mình.","e":{"tamma":-5,"xp":2}}]}],"ket":{"K01":{"ten":"Cơn đói dưới trời trống","canh":["Ngươi đứng giữa cửa hang và kéo cả luồng khí đang dâng về phía mình. Khi ngọn đèn ngoài cửa tắt, đến gió trên dốc cũng thôi thổi ngang mặt.","Người từng chia cơm đặt bát gần chân ngươi, gọi tới khản tiếng. Ngươi còn thấy hơi ấm từ cổ tay họ, nhưng đã quên cách đưa tay nhận bát."]},"K02":{"ten":"Tiếng gõ từ trong ngực","canh":["Ngươi vừa định vận khí thì những luồng đã nuốt cùng dồn ngược lên ngực. Tiếng gõ nổi lên từ trong người, ép ngươi rời chiếu mà vẫn chẳng đứng được.","Người giữ đèn kê bát nước cạnh ngươi rồi chạy đi gọi người chữa. Tới lúc họ trở lại, bát đã nguội và lòng bàn tay ngươi nằm mở trên nền."]}}}};
